  GAME_DANGER_ZONE_PRIMARY_CONTROL_ID,
} from "./danger-zone-tab";
import {
  GameCompatibilitySettingsTab,
  GAME_COMPATIBILITY_SETTINGS_PRIMARY_CONTROL_ID,
} from "./compatibility-tab";
import {
  shouldShowCloudSaveV2Tab,
  shouldShowLegacyCloudSaveTab,
} from "./cloud-tab-visibility";

type GameSettingsTabId =
  | "launch"
  | "customization"
  | "hydra_cloud"
  | "hydra_cloud_legacy"
  | "compatibility"
  | "downloads"
  | "danger_zone";

const GAME_SETTINGS_TAB_FOCUS_IDS: Record<GameSettingsTabId, string> = {
  launch: GAME_LAUNCH_SETTINGS_PRIMARY_CONTROL_ID,
  customization: GAME_CUSTOMIZATION_SETTINGS_PRIMARY_CONTROL_ID,
  hydra_cloud: GAME_CLOUD_V2_SETTINGS_PRIMARY_CONTROL_ID,
  hydra_cloud_legacy: GAME_CLOUD_SETTINGS_PRIMARY_CONTROL_ID,
  downloads: GAME_DOWNLOADS_SETTINGS_PRIMARY_CONTROL_ID,
  danger_zone: GAME_DANGER_ZONE_PRIMARY_CONTROL_ID,
  compatibility: GAME_COMPATIBILITY_SETTINGS_PRIMARY_CONTROL_ID,
};

interface GameSettingsModalProps {
  visible: boolean;
  game: LibraryGame;
  launchSettings: GameLaunchSettingsProps;
  customizationSettings: GameCustomizationSettingsProps;
  cloudSettings: GameCloudSettingsProps;
  onClose: () => void;
}

export function GameSettingsModal({
  visible,
  game,
  launchSettings,
  customizationSettings,
  cloudSettings,
  onClose,
}: Readonly<GameSettingsModalProps>) {
  const { t } = useTranslation(["game_details", "header"]);
  const [activeTabId, setActiveTabId] = useState<GameSettingsTabId>("launch");
  const { userDetails, hasActiveSubscription } = useUserDetails();
  const preferredAssets = useMemo(
    () => resolvePreferredGameAssets(game, null),
    [game]
  );
  const isDev = import.meta.env.DEV;
  const shouldShowCompatibilityTab =
    globalThis.window.electron.platform === "linux" || isDev;
  const settingsLabel = t("settings", { ns: "header" });

  useEffect(() => {
    if (visible) {
      setActiveTabId("launch");
    }
  }, []);

  const launchContent = useMemo(
    () => <GameLaunchSettingsTab {...launchSettings} />,
    [launchSettings]
  );
  const customizationContent = useMemo(
    () => <GameCustomizationSettingsTab {...customizationSettings} />,
    [customizationSettings]
  );
  const cloudContent = useMemo(
    () => <GameCloudSettingsTab {...cloudSettings} />,
    [cloudSettings]
  );
  const handleSelectExecutableFromCloudV2 = useCallback(() => {
    setActiveTabId("launch");
  }, []);
  const cloudV2Content = useMemo(
    () => (
      <GameCloudV2SettingsTab
        onSelectExecutable={handleSelectExecutableFromCloudV2}
      />
    ),
    [handleSelectExecutableFromCloudV2]
  );
  const downloadContent = useMemo(
    () => <GameDownloadsSettingsTab game={game} />,
    [game]
  );
  const dangerContent = useMemo(
    () => <GameDangerZoneSettingsTab game={game} onClose={onClose} />,
    [game, onClose]
  );
  const compatibilityContent = useMemo(
    () => <GameCompatibilitySettingsTab game={game} />,
    [game]
  );

  const isSignedIn = userDetails !== null;
  const shouldShowCloudV2Tab = shouldShowCloudSaveV2Tab(
    game.shop,
    isSignedIn,
    hasActiveSubscription
  );
  const shouldShowLegacyCloudTab = shouldShowLegacyCloudSaveTab(
    game.shop,
    isSignedIn,
    hasActiveSubscription
  );

  useEffect(() => {
    const isUnavailableCloudTab =
      (activeTabId === "hydra_cloud" && !shouldShowCloudV2Tab) ||
      (activeTabId === "hydra_cloud_legacy" && !shouldShowLegacyCloudTab);

    if (isUnavailableCloudTab) {
      setActiveTabId("launch");
    }
  }, [activeTabId, shouldShowCloudV2Tab, shouldShowLegacyCloudTab]);

  const tabs = useMemo<SidebarModalTab<GameSettingsTabId>[]>(
    () => [
      {
        id: "launch",
        label: t("settings_category_launch"),
        content: launchContent,
      },
      {
        id: "customization",
        label: t("settings_category_customization"),
        content: customizationContent,
      },
      ...(shouldShowCloudV2Tab
        ? [
            {
              id: "hydra_cloud",
              label: t("settings_category_hydra_cloud"),
              content: cloudV2Content,
            } satisfies SidebarModalTab<GameSettingsTabId>,
          ]
        : []),
      ...(shouldShowLegacyCloudTab
        ? [
            {
              id: "hydra_cloud_legacy",
              label: t("settings_category_hydra_cloud"),
              content: cloudContent,
            } satisfies SidebarModalTab<GameSettingsTabId>,
          ]
        : []),
      ...(shouldShowCompatibilityTab
        ? [
            {
              id: "compatibility",
              label: t("settings_category_compatibility"),
              content: compatibilityContent,
            } satisfies SidebarModalTab<GameSettingsTabId>,
          ]
        : []),
      {
        id: "downloads",
        label: t("settings_category_downloads"),
        content: downloadContent,
      },
      {
        id: "danger_zone",
        label: t("settings_category_danger_zone"),
        content: dangerContent,
      },
    ],
    [
      cloudContent,
      cloudV2Content,
      compatibilityContent,
      customizationContent,
      dangerContent,
      downloadContent,
      launchContent,
      shouldShowCloudV2Tab,
      shouldShowLegacyCloudTab,
      shouldShowCompatibilityTab,
      t,
    ]
  );

  return (
    <SidebarModal
      visible={visible}
      onClose={onClose}
      title={settingsLabel}
      coverImage={preferredAssets.heroSrc || undefined}
      className="game-settings-modal"
      ariaLabel={settingsLabel}
      contentEntryFocusId={GAME_SETTINGS_TAB_FOCUS_IDS[activeTabId]}
      tabs={tabs}
      activeTabId={activeTabId}
      onActiveTabChange={setActiveTabId}
    />
  );
}

import { useEffect, useState } from "react";
import { IS_DESKTOP } from "../../constants";
import type { DownloadSource, Game, GameRepack } from "@types";
import { applyHosterAvailability, fetchHosterAvailability } from "@shared";
import { orderBy } from "lodash-es";

export type DownloadOptionsEmptyStateReason =
  | "no-configured-sources"
  | "no-game-sources"
  | "no-download-options";

function getKnownGameSourcesEmptyStateReason(
  downloadSources: string[] | undefined
): DownloadOptionsEmptyStateReason | null {
  if (Array.isArray(downloadSources) && downloadSources.length === 0) {
    return "no-game-sources";
  }

  return null;
}

interface DownloadStateSetters {
  setDownloadOptions: (v: GameRepack[]) => void;
  setLocalDownloadSources: (v: DownloadSource[]) => void;
  setIsCheckingSources: (v: boolean) => void;
  setIsLoading: (v: boolean) => void;
  setEmptyStateReason: (v: DownloadOptionsEmptyStateReason | null) => void;
}

function applyIfNotCancelled(
  signal: { cancelled: boolean },
  apply: () => void
) {
  if (!signal.cancelled) {
    apply();
  }
}

function resetDownloadOptionsState(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters
) {
  applyIfNotCancelled(signal, () => {
    setters.setDownloadOptions([]);
    setters.setLocalDownloadSources([]);
    setters.setIsCheckingSources(true);
    setters.setIsLoading(false);
    setters.setEmptyStateReason(null);
  });
}

function setNoConfiguredSourcesState(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters
) {
  applyIfNotCancelled(signal, () => {
    setters.setLocalDownloadSources([]);
    setters.setDownloadOptions([]);
    setters.setIsCheckingSources(false);
    setters.setIsLoading(false);
    setters.setEmptyStateReason("no-configured-sources");
  });
}

function setKnownEmptyState(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters,
  reason: DownloadOptionsEmptyStateReason
) {
  applyIfNotCancelled(signal, () => {
    setters.setDownloadOptions([]);
    setters.setIsCheckingSources(false);
    setters.setIsLoading(false);
    setters.setEmptyStateReason(reason);
  });
}

function startRemoteDownloadOptionsLoading(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters
) {
  applyIfNotCancelled(signal, () => {
    setters.setIsCheckingSources(false);
    setters.setIsLoading(true);
  });
}

function setDownloadOptionsSuccessState(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters,
  options: GameRepack[]
) {
  applyIfNotCancelled(signal, () => {
    setters.setDownloadOptions(options);
    setters.setEmptyStateReason(
      options.length === 0 ? "no-download-options" : null
    );
    setters.setIsCheckingSources(false);
    setters.setIsLoading(false);
  });
}

function setNoDownloadOptionsState(
  signal: { cancelled: boolean },
  setters: DownloadStateSetters
) {
  applyIfNotCancelled(signal, () => {
    setters.setDownloadOptions([]);
    setters.setEmptyStateReason("no-download-options");
    setters.setIsCheckingSources(false);
    setters.setIsLoading(false);
  });
}

async function fetchDownloadOptions(
  game: Pick<Game, "objectId" | "shop">,
  signal: { cancelled: boolean },
  setters: DownloadStateSetters,
  knownGameSourcesEmptyStateReason: DownloadOptionsEmptyStateReason | null
) {
  resetDownloadOptionsState(signal, setters);

  let sortedSources: DownloadSource[] = [];

  try {
    const sources = (await globalThis.window.electron.leveldb.values(
      "downloadSources"
    )) as DownloadSource[];
    sortedSources = orderBy(sources, "createdAt", "desc");

    applyIfNotCancelled(signal, () => {
      setters.setLocalDownloadSources(sortedSources);
    });
  } catch {
    setNoConfiguredSourcesState(signal, setters);
    return;
  }

  if (sortedSources.length === 0) {
    setNoConfiguredSourcesState(signal, setters);
    return;
  }

  if (knownGameSourcesEmptyStateReason !== null) {
    setKnownEmptyState(signal, setters, knownGameSourcesEmptyStateReason);
    return;
  }

  startRemoteDownloadOptionsLoading(signal, setters);

  try {
    const endpoint = `/games/${game.shop}/${game.objectId}/download-sources`;

    const options = await globalThis.window.electron.hydraApi.get<GameRepack[]>(
      endpoint,
      {
        params: {
          take: 100,
          skip: 0,
          downloadSourceIds: sortedSources.map((source) => source.id),
        },
        needsAuth: false,
      }
    );

    setDownloadOptionsSuccessState(signal, setters, options);

    if (signal.cancelled || !Array.isArray(options) || options.length === 0) {
      return;
    }

    const results = await fetchHosterAvailability(options, (url, data) =>
      globalThis.window.electron.hydraApi.post(url, { data, needsAuth: false })
    );

    if (results.length === 0) return;

    applyIfNotCancelled(signal, () => {
      setters.setDownloadOptions(applyHosterAvailability(options, results));
    });
  } catch {
    setNoDownloadOptionsState(signal, setters);
  }
}

export function useGameDownloadOptions(
  game: Pick<Game, "objectId" | "shop"> & {
    downloadSources?: string[];
  },
  visible: boolean
) {
  const shouldLoadDownloadOptions =
    visible && IS_DESKTOP && game.shop !== "custom";
  const knownGameSourcesEmptyStateReason = getKnownGameSourcesEmptyStateReason(
    game.downloadSources
  );
  const downloadSourcesDependencyKey = Array.isArray(game.downloadSources)
    ? game.downloadSources.join("|")
    : "__unknown__";
  const [downloadOptions, setDownloadOptions] = useState<GameRepack[]>([]);
  const [localDownloadSources, setLocalDownloadSources] = useState<
    DownloadSource[]
  >([]);
  const [isCheckingSources, setIsCheckingSources] = useState(
    shouldLoadDownloadOptions && knownGameSourcesEmptyStateReason === null
  );
  const [isLoading, setIsLoading] = useState(
    shouldLoadDownloadOptions && knownGameSourcesEmptyStateReason === null
  );
  const [emptyStateReason, setEmptyStateReason] =
    useState<DownloadOptionsEmptyStateReason | null>(
      shouldLoadDownloadOptions ? knownGameSourcesEmptyStateReason : null
    );

  useEffect(() => {
    if (!shouldLoadDownloadOptions) {
      setDownloadOptions([]);
      setLocalDownloadSources([]);
      setIsCheckingSources(false);
      setIsLoading(false);
      setEmptyStateReason(null);
      return;
    }

    if (knownGameSourcesEmptyStateReason !== null) {
      setDownloadOptions([]);
      setLocalDownloadSources([]);
      setIsCheckingSources(false);
      setIsLoading(false);
      setEmptyStateReason(knownGameSourcesEmptyStateReason);
      return;
    }

    const signal = { cancelled: false };

    void fetchDownloadOptions(
      game,
      signal,
      {
        setDownloadOptions,
        setLocalDownloadSources,
        setIsCheckingSources,
        setIsLoading,
        setEmptyStateReason,
      },
      knownGameSourcesEmptyStateReason
    );

    return () => {
      signal.cancelled = true;
    };
  }, [
    downloadSourcesDependencyKey,
    game.objectId,
    game.shop,
    knownGameSourcesEmptyStateReason,
    shouldLoadDownloadOptions,
  ]);

  return {
    downloadOptions,
    localDownloadSources,
    isCheckingSources,
    isLoading,
    emptyStateReason,
  };
}

