        id: renderedActiveDownload.id,
        title: renderedActiveDownload.title,
        href: renderedActiveDownload.href,
        backgroundImageUrl,
        logoImageUrl,
        accentImageUrl: backgroundImageUrl,
        accentColor: null,
        pauseOrResumeLabel: "Pause Download",
        canPauseOrResume: false,
        progressPanel: {
          title: "Move Preview",
          progress: 0,
          progressLabel: "0%",
