    if (!root) return;

    const frameId = globalThis.window.requestAnimationFrame(() => {
      const target = resolvePreviewTargetElement(
        root,
        dragPreviewState,
        dragSource.gameId
      );
      if (!target) return;

      scrollPreviewTargetIntoView(
        root,
        target,
        dragTarget?.kind === "hero" ? "prefer-center" : "keep-visible"
      );
    });

    return () => {
