const SPEED_HISTORY_SAMPLE_SIZE = 120;

export function getDownloadCoverImageUrl(
  game: Pick<
    LibraryGame,
    | "customHeroImageUrl"
    | "libraryHeroImageUrl"
    | "coverImageUrl"
    | "libraryImageUrl"
    | "customIconUrl"
    | "iconUrl"
  >
): string | null {
  return (
    [
      game.customHeroImageUrl,
      game.libraryHeroImageUrl,
      game.coverImageUrl,
      game.libraryImageUrl,
      game.customIconUrl,
      game.iconUrl,
    ]
      .map((source) => resolveImageSource(source))
      .find(Boolean) ?? null
  );
}

export function getDownloadLogoImageUrl(
  game: Pick<LibraryGame, "customLogoImageUrl" | "logoImageUrl">
): string | null {
  return (
    [game.customLogoImageUrl, game.logoImageUrl]
      .map((source) => resolveImageSource(source))
      .find(Boolean) ?? null
  );
}

function formatProgress(progress?: number) {
  if (!progress) return "0%";

  const percentage = progress * 100;

  if (Number.isInteger(percentage)) {
    return `${percentage}%`;
  }

  return `${percentage.toFixed(1)}%`;
}

function formatSpeed(
  value: number,
  userPreferences: UserPreferences | null
): string {
  if (value <= 0) return "0 B/s";

  return userPreferences?.showDownloadSpeedInMegabytes
    ? `${formatBytes(value)}/s`
    : formatBytesToMbps(value);
}

function getDownloadSize(download: LibraryGame["download"]) {
  return download?.fileSize != null
    ? formatBytes(download.fileSize)
    : "Unknown";
}

function getDownloadMetaLabel(game: LibraryGame) {
  const download = game.download;

  if (!download) return "Not downloaded";

  return DOWNLOADER_NAME[download.downloader];
}

function getErrorStatusLabel(download: LibraryGame["download"]) {
  if (!download) return "Error";
  return download.status === "error" ? "Error" : "Paused";
}

function formatTransfer(
  bytesDownloaded?: number | null,
  fileSize?: number | null
): string | null {
  if (bytesDownloaded == null && fileSize == null) return null;
  if (bytesDownloaded == null)
    return fileSize != null ? formatBytes(fileSize) : null;
  if (fileSize == null) return formatBytes(bytesDownloaded);

  return `${formatBytes(bytesDownloaded)} / ${formatBytes(fileSize)}`;
}

function getEtaLabel(
  timeRemaining: number | null | undefined,
  formatDistance: ReturnType<typeof useDate>["formatDistance"]
) {
  if (
    timeRemaining == null ||
    timeRemaining <= 0 ||
    !Number.isFinite(timeRemaining)
  ) {
    return null;
  }

  return formatDistance(
    addMilliseconds(new Date(), timeRemaining),
    new Date(),
    { addSuffix: true }
  );
}

function getFinishedAtLabel(
  timestamp: number | null | undefined,
  t: (key: string, options?: Record<string, unknown>) => string,
  formatTime: (date: number | Date | string) => string
) {
  if (timestamp == null || !Number.isFinite(timestamp)) {
    return "Finished";
  }

  try {
    return t("downloads_finished_at", {
      time: formatTime(new Date(timestamp)),
    });
  } catch {
    return "Finished";
  }
}

export function useBigPictureDownloadsPageData() {
  const { library, updateLibrary } = useLibrary();
  const { layoutState } = useDownloadLayout();
  const { formatDistance, formatTime } = useDate();
  const { t } = useTranslation("big_picture");
  const [userPreferences, setUserPreferences] =
    useState<UserPreferences | null>(null);
  const [renderTick, setRenderTick] = useState(0);
  const lastPacket = useBigPictureDownloadsStore((state) => state.lastPacket);
  const seedingStatuses = useBigPictureDownloadsStore(
    (state) => state.seedingStatuses
  );
  const extractionProgressByGameId = useBigPictureDownloadsStore(
    (state) => state.extractionProgressByGameId
  );
  const speedHistoryByGameId = useBigPictureDownloadsStore(
    (state) => state.speedHistoryByGameId
  );
  const peakSpeedByGameId = useBigPictureDownloadsStore(
    (state) => state.peakSpeedByGameId
  );
  const setLastPacket = useBigPictureDownloadsStore(
    (state) => state.setLastPacket
  );

  useEffect(() => {
    if (!IS_DESKTOP) return;

    initializeBigPictureDownloadsStore();
  }, []);

  useEffect(() => {
    if (!IS_DESKTOP) return;

    globalThis.window.electron
      .getUserPreferences()
      .then((preferences) => {
        setUserPreferences(preferences);
      })
      .catch(() => {
        setUserPreferences(null);
      });
  }, []);

  useEffect(() => {
    const hasSeedingActivity = seedingStatuses.some(
      (status) => status.status === "seeding" && status.uploadSpeed > 0
    );
    const shouldTick = Boolean(lastPacket || hasSeedingActivity);

    if (!shouldTick) return;

    const interval = globalThis.window.setInterval(() => {
      setRenderTick((current) => current + 1);
    }, 1000);

    return () => {
      globalThis.window.clearInterval(interval);
    };
  }, [lastPacket, seedingStatuses]);

  const downloadsById = useMemo(() => {
    return new Map(
      library
        .filter((game) => game.download && game.download.status !== "removed")
        .map((game) => [game.id, game])
    );
  }, [library]);

  const downloadView = useMemo(() => {
    const downloads = library
      .map((game) => game.download)
      .filter((download): download is NonNullable<typeof download> => {
        return Boolean(download && download.status !== "removed");
      });

    return getBigPictureDownloadView(downloads, layoutState);
  }, [layoutState, library]);

  const activeGame = useMemo(() => {
    if (!downloadView.heroId) return null;
    return downloadsById.get(downloadView.heroId) ?? null;
  }, [downloadView.heroId, downloadsById]);

  const queuedGames = useMemo(() => {
    return downloadView.queueIds
      .map((id) => downloadsById.get(id) ?? null)
      .filter((game): game is LibraryGame => game !== null);
  }, [downloadView.queueIds, downloadsById]);

  const pausedGames = useMemo(() => {
    return downloadView.pausedIds
      .map((id) => downloadsById.get(id) ?? null)
      .filter((game): game is LibraryGame => game !== null);
  }, [downloadView.pausedIds, downloadsById]);

  const completedGames = useMemo(() => {
    return downloadView.completedIds
      .map((id) => downloadsById.get(id) ?? null)
      .filter((game): game is LibraryGame => game !== null);
  }, [downloadView.completedIds, downloadsById]);

  const activeDownload = useMemo((): BigPictureActiveDownloadItem | null => {
    if (!activeGame?.download) return null;

    const download = activeGame.download;
    const isExtracting = download.extracting;
    const isPausedHero = download.status === "paused";
    const extractionProgress =
      extractionProgressByGameId[activeGame.id] ?? download.extractionProgress;
    const shouldUseLivePacket =
      !isPausedHero && lastPacket?.gameId === activeGame.id;
    const packetProgress = lastPacket?.progress ?? download.progress;
    const progress = isExtracting
      ? extractionProgress
      : shouldUseLivePacket
        ? Math.max(packetProgress, download.progress)
        : download.progress;
    const packetBytesDownloaded =
      lastPacket?.download.bytesDownloaded ?? download.bytesDownloaded;
    const bytesDownloaded = isExtracting
      ? download.fileSize != null
        ? Math.round(download.fileSize * progress)
        : download.bytesDownloaded
      : shouldUseLivePacket
        ? Math.max(packetBytesDownloaded, download.bytesDownloaded)
        : download.bytesDownloaded;
    const sizeInBytes = shouldUseLivePacket
      ? (lastPacket?.download.fileSize ?? download.fileSize)
      : download.fileSize;
    const eta =
      !isExtracting && shouldUseLivePacket
        ? getEtaLabel(lastPacket?.timeRemaining, formatDistance)
        : null;

    let statusLabel = "Active";
    let statusTone: DownloadTone = "active";
    let speedLabel = "0 B/s";
    let pauseOrResumeAction: "pause" | "resume" = "pause";
    const canPauseOrResume = !isExtracting;

    if (download.status === "error") {
      statusLabel = "Error";
      statusTone = "error";
      speedLabel = "Retry available";
      pauseOrResumeAction = "resume";
    } else if (isPausedHero) {
      statusLabel = "Paused";
      statusTone = "paused";
      speedLabel = "Paused";
      pauseOrResumeAction = "resume";
    } else if (isExtracting) {
      statusLabel = "Extracting";
    } else if (lastPacket?.isRecovering) {
      statusLabel = `Recovering download… ${Math.round(
        (lastPacket.recoveryProgress ?? 0) * 100
      )}%`;
    } else if (lastPacket?.isReconnecting) {
      statusLabel = "Reconnecting…";
    } else if (lastPacket?.isCheckingFiles) {
      statusLabel = "Checking files";
    } else if (lastPacket?.isDownloadingMetadata) {
      statusLabel = "Downloading metadata";
    } else {
      statusLabel = "In progress";
    }

    if (!isPausedHero && download.status !== "error") {
      speedLabel = isExtracting
        ? "Preparing files"
        : formatSpeed(lastPacket?.downloadSpeed ?? 0, userPreferences);
    }

    return {
      id: activeGame.id,
      title: activeGame.title,
      href: getBigPictureGameDetailsPath(activeGame),
      coverImageUrl: getDownloadCoverImageUrl(activeGame),
      metaLabel: getDownloadMetaLabel(activeGame),
      statusLabel,
      statusTone,
      progress,
      progressLabel: formatProgress(progress),
      transferLabel:
        formatTransfer(bytesDownloaded, sizeInBytes) ??
        formatBytes(bytesDownloaded),
      speedLabel,
      etaLabel: eta,
      sizeLabel: sizeInBytes != null ? formatBytes(sizeInBytes) : "Unknown",
      pauseOrResumeAction,
      canPauseOrResume,
      canMoveFromHero: !isExtracting,
      canPromoteToHero: !isExtracting,
      game: activeGame,
    };
  }, [
    activeGame,
    extractionProgressByGameId,
    formatDistance,
    lastPacket,
    renderTick,
    userPreferences,
  ]);

  const queuedDownloads = useMemo((): BigPictureDownloadListItem[] => {
    return queuedGames.map((game, index) => {
      const download = game.download;

      return {
        id: game.id,
        title: game.title,
        href: getBigPictureGameDetailsPath(game),
        coverImageUrl: getDownloadCoverImageUrl(game),
        metaLabel: getDownloadMetaLabel(game),
        statusLabel: "Queued",
        statusTone: "default",
        progress: download?.progress ?? 0,
        trailingLabel: getDownloadSize(download),
        secondaryLabel:
          formatTransfer(download?.bytesDownloaded, download?.fileSize) ??
          getDownloadSize(download),
        rightStatusLabel: null,
        progressLabel: formatProgress(download?.progress ?? 0),
        transferLabel: formatTransfer(
          download?.bytesDownloaded,
          download?.fileSize
        ),
        sizeLabel: getDownloadSize(download),
        queuePosition: index,
        seedAction: null,
        canRemove: false,
        canMoveUp: index > 0,
        canMoveDown: index < queuedGames.length - 1,
        game,
      };
    });
  }, [queuedGames]);

  const pausedDownloads = useMemo((): BigPictureDownloadListItem[] => {
    return pausedGames.map((game, index) => {
      const download = game.download;
      const isError = download?.status === "error";

      return {
        id: game.id,
        title: game.title,
        href: getBigPictureGameDetailsPath(game),
        coverImageUrl: getDownloadCoverImageUrl(game),
        metaLabel: getDownloadMetaLabel(game),
        statusLabel: isError ? getErrorStatusLabel(download) : "Paused",
        statusTone: isError ? "error" : "paused",
        progress: download?.progress ?? 0,
        trailingLabel: formatProgress(download?.progress ?? 0),
        secondaryLabel:
          formatTransfer(download?.bytesDownloaded, download?.fileSize) ??
          getDownloadSize(download),
        rightStatusLabel: null,
        progressLabel: formatProgress(download?.progress ?? 0),
        transferLabel: formatTransfer(
          download?.bytesDownloaded,
          download?.fileSize
        ),
        sizeLabel: getDownloadSize(download),
        seedAction: null,
        canRemove: false,
        canMoveUp: index > 0,
        canMoveDown: index < pausedGames.length - 1,
        game,
      };
    });
  }, [pausedGames]);

  const completedDownloads = useMemo((): BigPictureDownloadListItem[] => {
    return completedGames.map((game) => {
      const seedingStatus = seedingStatuses.find(
        (status) => status.gameId === game.id
      );
      const download = game.download;

      let statusLabel = "Completed";
      let statusTone: DownloadTone = "success";
      let trailingLabel = getDownloadSize(download);
      let rightStatusLabel = getFinishedAtLabel(
        download?.timestamp,
        t,
        formatTime
      );
      let seedAction: BigPictureDownloadListItem["seedAction"] = null;

      if (
        download?.status === "seeding" ||
        seedingStatus?.status === "seeding"
      ) {
        statusLabel = "Seeding";
        statusTone = "active";
        trailingLabel = formatSpeed(
          seedingStatus?.uploadSpeed ?? 0,
          userPreferences
        );
        rightStatusLabel = `Seeding: ${trailingLabel}`;
        seedAction = "pause";
      } else if (
        download?.status === "complete" &&
        download.downloader === Downloader.Torrent
      ) {
        seedAction = "resume";
      }

      return {
        id: game.id,
        title: game.title,
        href: getBigPictureGameDetailsPath(game),
        coverImageUrl: getDownloadCoverImageUrl(game),
        metaLabel: getDownloadMetaLabel(game),
        statusLabel,
        statusTone,
        progress: download?.progress ?? null,
        trailingLabel,
        secondaryLabel:
          formatTransfer(download?.bytesDownloaded, download?.fileSize) ??
          getDownloadSize(download),
        rightStatusLabel,
        progressLabel:
          download?.status === "error"
            ? formatProgress(download.progress)
            : null,
        transferLabel:
          download?.status === "error"
            ? formatTransfer(download.bytesDownloaded, download.fileSize)
            : null,
        speedLabel:
          download?.status === "seeding" || seedingStatus?.status === "seeding"
            ? formatSpeed(seedingStatus?.uploadSpeed ?? 0, userPreferences)
            : null,
        sizeLabel: getDownloadSize(download),
        seedAction,
        canRemove: true,
        canMoveUp: false,
        canMoveDown: false,
        game,
      };
    });
  }, [
    completedGames,
    formatTime,
    renderTick,
    seedingStatuses,
    t,
    userPreferences,
  ]);

  const hasDownloads = Boolean(
    activeDownload ||
      queuedDownloads.length ||
      pausedDownloads.length ||
      completedDownloads.length
  );

  const networkStats = useMemo((): BigPictureDownloadsNetworkStats => {
    const speedHistory = activeGame
      ? (speedHistoryByGameId[activeGame.id] ?? [])
      : [];
    const peakSpeed = activeGame ? (peakSpeedByGameId[activeGame.id] ?? 0) : 0;
    const speedHistorySamples =
      speedHistory.length >= SPEED_HISTORY_SAMPLE_SIZE
        ? speedHistory
        : [
            ...Array.from(
              { length: SPEED_HISTORY_SAMPLE_SIZE - speedHistory.length },
              () => 0
            ),
            ...speedHistory,
          ];
    const speedHistoryLabels = speedHistorySamples.map((value) =>
      formatSpeed(value, userPreferences)
    );

    if (!activeGame?.download || !activeDownload) {
      return {
        speedLabel: "0 B/s",
        peakSpeedLabel: "0 B/s",
        speedHistory: speedHistorySamples,
        speedHistoryLabels,
        seeds: null,
        peers: null,
        showSeedsAndPeers: false,
      };
    }

    if (activeDownload.pauseOrResumeAction === "resume") {
      return {
        speedLabel: "0 B/s",
        peakSpeedLabel: formatSpeed(peakSpeed, userPreferences),
        speedHistory: speedHistorySamples,
        speedHistoryLabels,
        seeds: null,
        peers: null,
        showSeedsAndPeers: false,
      };
    }

    const shouldZeroSpeed =
      activeGame.download.extracting ||
      lastPacket?.isReconnecting ||
      lastPacket?.isCheckingFiles ||
      lastPacket?.isDownloadingMetadata ||
      lastPacket?.gameId !== activeGame.id;

    const showSeedsAndPeers =
      activeGame.download.downloader === Downloader.Torrent &&
      lastPacket?.gameId === activeGame.id;

    return {
      speedLabel: shouldZeroSpeed
        ? "0 B/s"
        : formatSpeed(lastPacket?.downloadSpeed ?? 0, userPreferences),
      peakSpeedLabel: formatSpeed(peakSpeed, userPreferences),
      speedHistory: speedHistorySamples,
      speedHistoryLabels,
      seeds: showSeedsAndPeers ? (lastPacket?.numSeeds ?? 0) : null,
      peers: showSeedsAndPeers ? (lastPacket?.numPeers ?? 0) : null,
      showSeedsAndPeers,
    };
  }, [
    activeDownload,
    activeGame,
    lastPacket?.downloadSpeed,
    lastPacket?.gameId,
    lastPacket?.isReconnecting,
    lastPacket?.isCheckingFiles,
    lastPacket?.isDownloadingMetadata,
    lastPacket?.numPeers,
    lastPacket?.numSeeds,
    peakSpeedByGameId,
    speedHistoryByGameId,
    userPreferences,
  ]);

  const pauseDownload = useCallback(
    async (game: LibraryGame) => {
      if (!IS_DESKTOP) return;

      await globalThis.window.electron.pauseGameDownload(
        game.shop,
        game.objectId
      );

      if (lastPacket?.gameId === game.id) {
        setLastPacket(null);
      }
    },
    [lastPacket?.gameId]
  );

  const startNow = useCallback(async (game: LibraryGame) => {
    if (!IS_DESKTOP) return;

    await globalThis.window.electron.moveDownloadPlacement(
      game.shop,
      game.objectId,
      "hero"
    );
  }, []);

  const resumeDownload = useCallback(async (game: LibraryGame) => {
    if (!IS_DESKTOP) return;

    await globalThis.window.electron.resumeGameDownload(
      game.shop,
      game.objectId,
      "queueIfActive"
    );
  }, []);

  const sendToQueue = useCallback(
    async (game: LibraryGame, targetIndex?: number) => {
      if (!IS_DESKTOP) return;

      const resolvedTargetIndex = targetIndex ?? queuedGames.length;

      await globalThis.window.electron.moveDownloadPlacement(
        game.shop,
        game.objectId,
        "queue",
        resolvedTargetIndex
      );
    },
    [queuedGames.length]
  );

  const moveToPaused = useCallback(
    async (game: LibraryGame, targetIndex?: number) => {
      if (!IS_DESKTOP) return;

      const resolvedTargetIndex = targetIndex ?? pausedGames.length;

      await globalThis.window.electron.moveDownloadPlacement(
        game.shop,
        game.objectId,
        "paused",
        resolvedTargetIndex
      );
    },
    [pausedGames.length]
  );

  const cancelDownload = useCallback(
    async (game: LibraryGame) => {
      if (!IS_DESKTOP) return;

      await globalThis.window.electron.cancelGameDownload(
        game.shop,
        game.objectId
      );

      if (lastPacket?.gameId === game.id) {
        setLastPacket(null);
      }

      await globalThis.window.electron.deleteGameFolder(
        game.shop,
        game.objectId
      );
    },
    [lastPacket?.gameId]
  );

  const removeDownload = useCallback(
    async (game: LibraryGame) => {
      if (!IS_DESKTOP || !game.download) return;

      if (game.download.status === "seeding") {
        await globalThis.window.electron.pauseGameSeed(
          game.shop,
          game.objectId
        );
      }

      await globalThis.window.electron.deleteGameFolder(
        game.shop,
        game.objectId
      );
      await updateLibrary();
    },
    [updateLibrary]
  );

  const moveQueuedDownload = useCallback(
    async (game: LibraryGame, direction: "up" | "down") => {
      if (!IS_DESKTOP) return;

      await globalThis.window.electron.updateDownloadQueuePosition(
        game.shop,
        game.objectId,
        direction
      );
    },
    []
  );

  const setQueuedDownloadPosition = useCallback(
    async (game: LibraryGame, targetIndex: number) => {
      if (!IS_DESKTOP) return;

      await globalThis.window.electron.setDownloadQueuePosition(
        game.shop,
        game.objectId,
        targetIndex
      );
    },
    []
  );

  const setPausedDownloadPosition = useCallback(
    async (game: LibraryGame, targetIndex: number) => {
      if (!IS_DESKTOP) return;

      await globalThis.window.electron.setPausedDownloadPosition(
        game.shop,
        game.objectId,
        targetIndex
      );
    },
    []
  );

  const pauseSeeding = useCallback(async (game: LibraryGame) => {
    if (!IS_DESKTOP) return;

    await globalThis.window.electron.pauseGameSeed(game.shop, game.objectId);
  }, []);

  const resumeSeeding = useCallback(async (game: LibraryGame) => {
    if (!IS_DESKTOP) return;

    await globalThis.window.electron.resumeGameSeed(game.shop, game.objectId);
  }, []);

  return {
    activeDownload,
    networkStats,
    queuedDownloads,
    pausedDownloads,
    completedDownloads,
    hasDownloads,
    pauseDownload,
    resumeDownload,
    startNow,
    sendToQueue,
    moveToPaused,
    cancelDownload,
    removeDownload,
    moveQueuedDownload,
    setQueuedDownloadPosition,
    setPausedDownloadPosition,
    pauseSeeding,
    resumeSeeding,
  };
}

import "./behavior-section.scss";

import { useEffect, useMemo, useState } from "react";

import { Checkbox, VerticalFocusGroup } from "../../components";
import type { FocusOverrides } from "../../services";
import { useUserPreferences } from "../../hooks";
import {
  BEHAVIOR_ITEM_FOCUS_IDS,
  BEHAVIOR_SECTION_REGION_ID,
  LANGUAGE_SECTION_BUTTON_ID,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface BehaviorSectionProps {
  className?: string;
}

interface BehaviorForm {
  preferQuitInsteadOfHiding: boolean;
  runAtStartup: boolean;
  startMinimized: boolean;
  hideToTrayOnGameStart: boolean;
  launchToLibraryPage: boolean;
  enableAutoInstall: boolean;
}

interface BehaviorItem {
  id: string;
  focusId: string;
  label: string;
  checked: boolean;
  disabled: boolean;
  onChange: (checked: boolean) => void;
}

const DEFAULT_FORM: BehaviorForm = {
  preferQuitInsteadOfHiding: false,
  runAtStartup: false,
  startMinimized: false,
  hideToTrayOnGameStart: false,
  launchToLibraryPage: false,
  enableAutoInstall: false,
};

export function BehaviorSection({ className }: Readonly<BehaviorSectionProps>) {
  const userPreferences = useUserPreferences();
  const [showRunAtStartup, setShowRunAtStartup] = useState(false);
  const [form, setForm] = useState<BehaviorForm>(DEFAULT_FORM);

  useEffect(() => {
    let isMounted = true;

    globalThis.window.electron
      .isPortableVersion()
      .then((isPortableVersion) => {
        if (!isMounted) return;

        setShowRunAtStartup(!isPortableVersion);
      })
      .catch(() => {
        if (!isMounted) return;

        setShowRunAtStartup(true);
      });

    return () => {
      isMounted = false;
    };
  }, []);

  useEffect(() => {
    if (!userPreferences) return;

    setForm({
      preferQuitInsteadOfHiding:
        userPreferences.preferQuitInsteadOfHiding ?? false,
      runAtStartup: userPreferences.runAtStartup ?? false,
      startMinimized: userPreferences.startMinimized ?? false,
      hideToTrayOnGameStart: userPreferences.hideToTrayOnGameStart ?? false,
      launchToLibraryPage: userPreferences.launchToLibraryPage ?? false,
      enableAutoInstall: userPreferences.enableAutoInstall ?? false,
    });
  }, [userPreferences]);

  const isLinux = globalThis.window.electron.platform === "linux";

  const updateUserPreferences = async (
    values: Partial<BehaviorForm>,
    autoLaunchOptions?: { enabled: boolean; minimized: boolean }
  ) => {
    const nextForm = { ...form, ...values };
    setForm(nextForm);

    await globalThis.window.electron.updateUserPreferences(values);

    if (autoLaunchOptions) {
      globalThis.window.electron.autoLaunch(autoLaunchOptions);
    }
  };

  const items = useMemo<BehaviorItem[]>(() => {
    const baseItems: BehaviorItem[] = [
      {
        id: "prefer-quit-instead-of-hiding",
        focusId: BEHAVIOR_ITEM_FOCUS_IDS.preferQuitInsteadOfHiding,
        label: "Quit app instead of hiding",
        checked: form.preferQuitInsteadOfHiding,
        disabled: false,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ preferQuitInsteadOfHiding: checked }),
      },
      {
        id: "hide-to-tray-on-game-start",
        focusId: BEHAVIOR_ITEM_FOCUS_IDS.hideToTrayOnGameStart,
        label: "Hide to tray on game start",
        checked: form.hideToTrayOnGameStart,
        disabled: false,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ hideToTrayOnGameStart: checked }),
      },
      ...(showRunAtStartup
        ? [
            {
              id: "launch-with-system",
              focusId: BEHAVIOR_ITEM_FOCUS_IDS.runAtStartup,
              label: "Launch with system",
              checked: form.runAtStartup,
              disabled: false,
              onChange: (checked: boolean) =>
                void updateUserPreferences(
                  { runAtStartup: checked },
                  {
                    enabled: checked,
                    minimized: form.startMinimized,
                  }
                ),
            },
            {
              id: "launch-minimized",
              focusId: BEHAVIOR_ITEM_FOCUS_IDS.startMinimized,
              label: "Launch minimized",
              checked: form.runAtStartup && form.startMinimized,
              disabled: !form.runAtStartup,
              onChange: (checked: boolean) =>
                void updateUserPreferences(
                  { startMinimized: checked },
                  {
                    enabled: form.runAtStartup,
                    minimized: checked,
                  }
                ),
            },
          ]
        : []),
      {
        id: "launch-to-library-page",
        focusId: BEHAVIOR_ITEM_FOCUS_IDS.launchToLibraryPage,
        label: "Launch Hydra in library page",
        checked: form.launchToLibraryPage,
        disabled: false,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ launchToLibraryPage: checked }),
      },
      ...(isLinux
        ? [
            {
              id: "enable-auto-install",
              focusId: BEHAVIOR_ITEM_FOCUS_IDS.enableAutoInstall,
              label: "Enable auto install",
              checked: form.enableAutoInstall,
              disabled: false,
              onChange: (checked: boolean) =>
                void updateUserPreferences({ enableAutoInstall: checked }),
            },
          ]
        : []),
    ];

    return baseItems;
  }, [form, isLinux, showRunAtStartup]);

  const navigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    const focusableItems = items.filter((item) => !item.disabled);

    return Object.fromEntries(
      focusableItems.map((item, index) => {
        const previousItem = focusableItems[index - 1];
        const nextItem = focusableItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : {
                  type: "item",
                  itemId: LANGUAGE_SECTION_BUTTON_ID,
                },
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : {
                  type: "block",
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [items]);

  return (
    <SettingsSection
      title="Behavior"
      description="Quality of Life stuff to make your experience better."
      className={className}
    >
      <VerticalFocusGroup regionId={BEHAVIOR_SECTION_REGION_ID} asChild>
        <div className="behavior-section__content">
          {items.map((item) => (
            <Checkbox
              key={item.id}
              id={item.id}
              label={item.label}
              checked={item.checked}
              disabled={item.disabled}
              focusId={item.focusId}
              navigationOverrides={navigationOverridesByFocusId[item.focusId]}
              block
              onChange={item.onChange}
            />
          ))}
        </div>
      </VerticalFocusGroup>
    </SettingsSection>
  );
}

import "./big-picture.scss";

import type { BigPictureDiagnosticsPosition } from "@types";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

import { Checkbox, DropdownSelect, VerticalFocusGroup } from "../../components";
import type { DropdownSelectOption } from "../../components/common/dropdown-select";
import { useUserPreferences } from "../../hooks";
import type { FocusOverrideTarget, FocusOverrides } from "../../services";
import {
  BIG_PICTURE_AUDIO_SECTION_REGION_ID,
  BIG_PICTURE_DIAGNOSTICS_POSITION_SELECT_ID,
  BIG_PICTURE_DIAGNOSTICS_SECTION_REGION_ID,
  BIG_PICTURE_ITEM_FOCUS_IDS,
  BIG_PICTURE_SECTION_REGION_ID,
  BIG_PICTURE_STARTUP_SECTION_REGION_ID,
  SETTINGS_HEADER_RETURN_TARGET,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface BigPictureSettingsSectionProps {
  className?: string;
}

interface BigPictureForm {
  launchInBigPicture: boolean;
  bigPictureSoundsEnabled: boolean;
  bigPictureVirtualKeyboardEnabled: boolean;
  bigPictureDiagnosticsEnabled: boolean;
  bigPictureDiagnosticsPosition: BigPictureDiagnosticsPosition;
}

interface BigPictureItem {
  id: string;
  focusId: string;
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

const DEFAULT_FORM: BigPictureForm = {
  launchInBigPicture: false,
  bigPictureSoundsEnabled: true,
  bigPictureVirtualKeyboardEnabled: true,
  bigPictureDiagnosticsEnabled: false,
  bigPictureDiagnosticsPosition: "bottom-center",
};

function getPositionLabel(
  position: BigPictureDiagnosticsPosition,
  t: (key: string) => string
) {
  return t(`settings_diagnostics_position_${position.replace(/-/g, "_")}`);
}

export function BigPictureSettingsSection({
  className,
}: Readonly<BigPictureSettingsSectionProps>) {
  const { t } = useTranslation("big_picture");
  const userPreferences = useUserPreferences();
  const [form, setForm] = useState<BigPictureForm>(DEFAULT_FORM);

  useEffect(() => {
    if (!userPreferences) return;

    setForm({
      launchInBigPicture: userPreferences.launchInBigPicture ?? false,
      bigPictureSoundsEnabled: userPreferences.bigPictureSoundsEnabled ?? true,
      bigPictureVirtualKeyboardEnabled:
        userPreferences.bigPictureVirtualKeyboardEnabled ?? true,
      bigPictureDiagnosticsEnabled:
        userPreferences.bigPictureDiagnosticsEnabled ?? false,
      bigPictureDiagnosticsPosition:
        userPreferences.bigPictureDiagnosticsPosition ?? "bottom-center",
    });
  }, [userPreferences]);

  const updateUserPreferences = useCallback(
    async (values: Partial<BigPictureForm>) => {
      setForm((current) => ({ ...current, ...values }));

      await globalThis.window.electron.updateUserPreferences(values);
    },
    []
  );

  const handleLaunchInBigPictureChange = useCallback(
    (checked: boolean) => {
      updateUserPreferences({ launchInBigPicture: checked });
    },
    [updateUserPreferences]
  );

  const handleBigPictureSoundsChange = useCallback(
    (checked: boolean) => {
      updateUserPreferences({ bigPictureSoundsEnabled: checked });
    },
    [updateUserPreferences]
  );

  const handleVirtualKeyboardChange = useCallback(
    (checked: boolean) => {
      updateUserPreferences({ bigPictureVirtualKeyboardEnabled: checked });
    },
    [updateUserPreferences]
  );

  const handleDiagnosticsEnabledChange = useCallback(
    (checked: boolean) => {
      updateUserPreferences({ bigPictureDiagnosticsEnabled: checked });
    },
    [updateUserPreferences]
  );

  const handleDiagnosticsPositionChange = useCallback(
    (position: BigPictureDiagnosticsPosition) => {
      updateUserPreferences({ bigPictureDiagnosticsPosition: position });
    },
    [updateUserPreferences]
  );

  const startupItems = useMemo<BigPictureItem[]>(() => {
    return [
      {
        id: "launch-in-big-picture",
        focusId: BIG_PICTURE_ITEM_FOCUS_IDS.launchInBigPicture,
        label: t("settings_launch_in_big_picture"),
        checked: form.launchInBigPicture,
        onChange: handleLaunchInBigPictureChange,
      },
    ];
  }, [form.launchInBigPicture, handleLaunchInBigPictureChange]);

  const inputItems = useMemo<BigPictureItem[]>(() => {
    return [
      {
        id: "enable-virtual-keyboard",
        focusId: BIG_PICTURE_ITEM_FOCUS_IDS.enableVirtualKeyboard,
        label: t("settings_enable_virtual_keyboard"),
        checked: form.bigPictureVirtualKeyboardEnabled,
        onChange: handleVirtualKeyboardChange,
      },
    ];
  }, [form.bigPictureVirtualKeyboardEnabled, handleVirtualKeyboardChange]);

  const audioItems = useMemo<BigPictureItem[]>(() => {
    return [
      {
        id: "enable-big-picture-sounds",
        focusId: BIG_PICTURE_ITEM_FOCUS_IDS.enableSounds,
        label: t("settings_enable_big_picture_sounds"),
        checked: form.bigPictureSoundsEnabled,
        onChange: handleBigPictureSoundsChange,
      },
    ];
  }, [form.bigPictureSoundsEnabled, handleBigPictureSoundsChange]);

  const diagnosticsItems = useMemo<BigPictureItem[]>(() => {
    return [
      {
        id: "enable-diagnostics",
        focusId: BIG_PICTURE_ITEM_FOCUS_IDS.enableDiagnostics,
        label: t("settings_enable_diagnostics"),
        checked: form.bigPictureDiagnosticsEnabled,
        onChange: handleDiagnosticsEnabledChange,
      },
    ];
  }, [form.bigPictureDiagnosticsEnabled, handleDiagnosticsEnabledChange]);

  const diagnosticsPositionOptions = useMemo<
    Array<DropdownSelectOption<BigPictureDiagnosticsPosition>>
  >(() => {
    return (
      [
        "top-left",
        "top-center",
        "top-right",
        "bottom-left",
        "bottom-center",
        "bottom-right",
      ] as BigPictureDiagnosticsPosition[]
    ).map((position) => ({
      value: position,
      label: getPositionLabel(position, t),
    }));
  }, []);

  const inputNavigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    const previousFallback: FocusOverrideTarget = {
      type: "item",
      itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableSounds,
    };

    return Object.fromEntries(
      inputItems.map((item, index) => {
        const previousItem = inputItems[index - 1];
        const nextItem = inputItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : previousFallback,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : {
                  type: "item",
                  itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableDiagnostics,
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [inputItems]);

  const audioNavigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    const previousFallback: FocusOverrideTarget = {
      type: "item",
      itemId: BIG_PICTURE_ITEM_FOCUS_IDS.launchInBigPicture,
    };

    return Object.fromEntries(
      audioItems.map((item, index) => {
        const previousItem = audioItems[index - 1];
        const nextItem = audioItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : previousFallback,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : {
                  type: "item",
                  itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableVirtualKeyboard,
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [audioItems]);

  const startupNavigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    return Object.fromEntries(
      startupItems.map((item, index) => {
        const previousItem = startupItems[index - 1];
        const nextItem = startupItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : SETTINGS_HEADER_RETURN_TARGET,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : {
                  type: "item",
                  itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableSounds,
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [startupItems]);

  const diagnosticsNavigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    const previousFallback: FocusOverrideTarget = {
      type: "item",
      itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableVirtualKeyboard,
    };

    return Object.fromEntries(
      diagnosticsItems.map((item, index) => {
        const previousItem = diagnosticsItems[index - 1];
        const nextItem = diagnosticsItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : previousFallback,
            down: (() => {
              if (nextItem) {
                return { type: "item" as const, itemId: nextItem.focusId };
              }
              if (form.bigPictureDiagnosticsEnabled) {
                return {
                  type: "item" as const,
                  itemId: BIG_PICTURE_DIAGNOSTICS_POSITION_SELECT_ID,
                };
              }
              return { type: "block" as const };
            })(),
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [diagnosticsItems, form.bigPictureDiagnosticsEnabled]);

  const diagnosticsSelectNavigationOverrides = useMemo<FocusOverrides>(
    () => ({
      up: {
        type: "item",
        itemId: BIG_PICTURE_ITEM_FOCUS_IDS.enableDiagnostics,
      },
      down: {
        type: "block",
      },
    }),
    []
  );

  return (
    <div
      className={
        className
          ? `big-picture-settings-section ${className}`
          : "big-picture-settings-section"
      }
    >
      <SettingsSection
        title={t("settings_startup_section_title")}
        description={t("settings_startup_section_description")}
      >
        <VerticalFocusGroup
          regionId={BIG_PICTURE_STARTUP_SECTION_REGION_ID}
          asChild
        >
          <div className="big-picture-settings-section__content">
            {startupItems.map((item) => (
              <Checkbox
                key={item.id}
                id={item.id}
                label={item.label}
                checked={item.checked}
                focusId={item.focusId}
                navigationOverrides={
                  startupNavigationOverridesByFocusId[item.focusId]
                }
                block
                onChange={item.onChange}
              />
            ))}
          </div>
        </VerticalFocusGroup>
      </SettingsSection>

      <SettingsSection
        title={t("settings_audio_section_title")}
        description={t("settings_audio_section_description")}
      >
        <VerticalFocusGroup
          regionId={BIG_PICTURE_AUDIO_SECTION_REGION_ID}
          asChild
        >
          <div className="big-picture-settings-section__content">
            {audioItems.map((item) => (
              <Checkbox
                key={item.id}
                id={item.id}
                label={item.label}
                checked={item.checked}
                focusId={item.focusId}
                navigationOverrides={
                  audioNavigationOverridesByFocusId[item.focusId]
                }
                block
                onChange={item.onChange}
              />
            ))}
          </div>
        </VerticalFocusGroup>
      </SettingsSection>

      <SettingsSection
        title={t("settings_input_section_title")}
        description={t("settings_input_section_description")}
      >
        <VerticalFocusGroup regionId={BIG_PICTURE_SECTION_REGION_ID} asChild>
          <div className="big-picture-settings-section__content">
            {inputItems.map((item) => (
              <Checkbox
                key={item.id}
                id={item.id}
                label={item.label}
                checked={item.checked}
                focusId={item.focusId}
                navigationOverrides={
                  inputNavigationOverridesByFocusId[item.focusId]
                }
                block
                onChange={item.onChange}
              />
            ))}
          </div>
        </VerticalFocusGroup>
      </SettingsSection>

      <SettingsSection
        title={t("settings_diagnostics_section_title")}
        description={t("settings_diagnostics_section_description")}
      >
        <VerticalFocusGroup
          regionId={BIG_PICTURE_DIAGNOSTICS_SECTION_REGION_ID}
          asChild
        >
          <div className="big-picture-settings-section__content">
            {diagnosticsItems.map((item) => (
              <Checkbox
                key={item.id}
                id={item.id}
                label={item.label}
                checked={item.checked}
                focusId={item.focusId}
                navigationOverrides={
                  diagnosticsNavigationOverridesByFocusId[item.focusId]
                }
                block
                onChange={item.onChange}
              />
            ))}

            <DropdownSelect
              className="big-picture-settings-section__select"
              label={t("settings_diagnostics_position")}
              value={form.bigPictureDiagnosticsPosition}
              options={diagnosticsPositionOptions}
              disabled={!form.bigPictureDiagnosticsEnabled}
              focusId={BIG_PICTURE_DIAGNOSTICS_POSITION_SELECT_ID}
              focusNavigationOverrides={diagnosticsSelectNavigationOverrides}
              onValueChange={handleDiagnosticsPositionChange}
            />
          </div>
        </VerticalFocusGroup>
      </SettingsSection>
    </div>
  );
}

import "./compatibility.scss";

import type { ProtonVersion } from "@types";
import {
  type MouseEvent as ReactMouseEvent,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import { GAMEMODE_SITE_URL, MANGOHUD_SITE_URL } from "@shared";

import { Button, Checkbox, Radio, VerticalFocusGroup } from "../../components";
import { useUserPreferences, useBigPictureToast } from "../../hooks";
import type { FocusOverrides } from "../../services";
import {
  COMPATIBILITY_COMMON_REDIST_BUTTON_ID,
  COMPATIBILITY_GAMEMODE_FOCUS_ID,
  COMPATIBILITY_MANGOHUD_FOCUS_ID,
  COMPATIBILITY_PROTON_OPTION_AUTO_FOCUS_ID,
  COMPATIBILITY_SECTION_REGION_ID,
  getCompatibilityProtonOptionFocusId,
  SETTINGS_HEADER_RETURN_TARGET,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface SettingsSectionProps {
  className?: string;
}

interface CompatibilityForm {
  defaultProtonPath: string;
  autoRunGamemode: boolean;
  autoRunMangohud: boolean;
}

interface CompatibilityPreferenceValues {
  defaultProtonPath?: string | null;
  autoRunGamemode?: boolean;
  autoRunMangohud?: boolean;
}

interface CompatibilityItem {
  focusId: string;
  render: (navigationOverrides: FocusOverrides) => React.JSX.Element;
  disabled?: boolean;
}

interface ProtonOption {
  focusId: string;
  value: string;
  title: string;
  description: string;
  disabled: boolean;
}

const DEFAULT_FORM: CompatibilityForm = {
  defaultProtonPath: "",
  autoRunGamemode: false,
  autoRunMangohud: false,
};

function getProtonSourceDescription(version: ProtonVersion | null) {
  if (!version) {
    return "Uses the default UMU-managed Proton version.";
  }

  if (
    version.source === "compatibility_tools" ||
    version.path.includes("compatibilitytools.d")
  ) {
    return "Installed in Steam compatibilitytools.d.";
  }

  return "Installed in Steam.";
}

export function CompatibilitySettingsSection({
  className,
}: Readonly<SettingsSectionProps>) {
  const userPreferences = useUserPreferences();
  const { showSuccessToast } = useBigPictureToast();
  const [form, setForm] = useState<CompatibilityForm>(DEFAULT_FORM);
  const [protonVersions, setProtonVersions] = useState<ProtonVersion[]>([]);
  const [protonVersionsLoaded, setProtonVersionsLoaded] = useState(false);
  const [gamemodeAvailable, setGamemodeAvailable] = useState(false);
  const [mangohudAvailable, setMangohudAvailable] = useState(false);
  const [canInstallCommonRedist, setCanInstallCommonRedist] = useState(false);
  const [installingCommonRedist, setInstallingCommonRedist] = useState(false);

  const isDev = import.meta.env.DEV;
  const isLinux = globalThis.window.electron.platform === "linux";
  const isWindows = globalThis.window.electron.platform === "win32";
  const shouldRenderProtonSection = isLinux || isDev;
  const shouldRenderBehaviorSection = isLinux || isDev;
  const shouldRenderCommonRedistSection = isWindows || isDev;
  const canUseProtonSection = isLinux;
  const canUseBehaviorSection = isLinux;
  const canUseCommonRedistSection = isWindows;

  useEffect(() => {
    if (!userPreferences) return;

    setForm({
      defaultProtonPath: userPreferences.defaultProtonPath ?? "",
      autoRunGamemode: userPreferences.autoRunGamemode ?? false,
      autoRunMangohud: userPreferences.autoRunMangohud ?? false,
    });
  }, [userPreferences]);

  useEffect(() => {
    if (!isLinux) {
      setGamemodeAvailable(false);
      setMangohudAvailable(false);
      return;
    }

    globalThis.window.electron
      .isGamemodeAvailable()
      .then(setGamemodeAvailable)
      .catch(() => setGamemodeAvailable(false));

    globalThis.window.electron
      .isMangohudAvailable()
      .then(setMangohudAvailable)
      .catch(() => setMangohudAvailable(false));
  }, [isLinux]);

  useEffect(() => {
    if (!isLinux) return;

    globalThis.window.electron
      .getInstalledProtonVersions()
      .then(setProtonVersions)
      .catch(() => setProtonVersions([]))
      .finally(() => setProtonVersionsLoaded(true));
  }, [isLinux]);

  useEffect(() => {
    if (!isLinux) return;

    if (!protonVersionsLoaded || !form.defaultProtonPath) return;

    const hasSelectedVersion = protonVersions.some(
      (version) => version.path === form.defaultProtonPath
    );

    if (!hasSelectedVersion) {
      setForm((currentForm) => ({
        ...currentForm,
        defaultProtonPath: "",
      }));
    }
  }, [form.defaultProtonPath, isLinux, protonVersions, protonVersionsLoaded]);

  useEffect(() => {
    if (!isWindows) return;

    globalThis.window.electron.canInstallCommonRedist().then((canInstall) => {
      setCanInstallCommonRedist(canInstall);
    });

    const intervalId = globalThis.window.setInterval(() => {
      globalThis.window.electron
        .canInstallCommonRedist()
        .then((canInstall) => {
          setCanInstallCommonRedist(canInstall);
        })
        .catch(() => {
          setCanInstallCommonRedist(false);
        });
    }, 1000 * 5);

    return () => {
      globalThis.window.clearInterval(intervalId);
    };
  }, [isWindows]);

  useEffect(() => {
    if (!isWindows) return;

    return globalThis.window.electron.onCommonRedistProgress(
      ({ log, complete }) => {
        if (log === "Installation timed out" || complete) {
          setInstallingCommonRedist(false);

          if (complete) {
            showSuccessToast("Installation Complete", {
              message:
                "Common redistributables have been installed successfully.",
            });
          }
        }
      }
    );
  }, [isWindows, showSuccessToast]);

  const updateCompatibilityPreferences = useCallback(
    async (values: CompatibilityPreferenceValues) => {
      setForm((currentForm) => ({
        ...currentForm,
        ...values,
        defaultProtonPath:
          values.defaultProtonPath === undefined
            ? currentForm.defaultProtonPath
            : (values.defaultProtonPath ?? ""),
      }));

      await globalThis.window.electron.updateUserPreferences(values);
    },
    []
  );

  const handleInstallCommonRedist = useCallback(async () => {
    setInstallingCommonRedist(true);

    try {
      await globalThis.window.electron.installCommonRedist();
    } catch {
      setInstallingCommonRedist(false);
    }
  }, []);

  const handleOpenExternalLink = useCallback(
    async (event: ReactMouseEvent<HTMLAnchorElement>, url: string) => {
      event.preventDefault();
      event.stopPropagation();
      await globalThis.window.electron.openExternal(url);
    },
    []
  );

  const protonOptions = useMemo<ProtonOption[]>(() => {
    const options: ProtonOption[] = [
      {
        focusId: COMPATIBILITY_PROTON_OPTION_AUTO_FOCUS_ID,
        value: "",
        title: "Auto",
        description: getProtonSourceDescription(null),
        disabled: !canUseProtonSection,
      },
    ];

    for (const version of protonVersions) {
      options.push({
        focusId: getCompatibilityProtonOptionFocusId(version.path),
        value: version.path,
        title: version.name,
        description: getProtonSourceDescription(version),
        disabled: !canUseProtonSection,
      });
    }

    return options;
  }, [canUseProtonSection, protonVersions]);

  const items = useMemo<CompatibilityItem[]>(() => {
    const nextItems: CompatibilityItem[] = [];

    if (shouldRenderProtonSection) {
      nextItems.push(
        ...protonOptions.map((option) => ({
          focusId: option.focusId,
          disabled: option.disabled,
          render: (navigationOverrides: FocusOverrides) => (
            <Radio
              key={option.focusId}
              id={option.focusId}
              label={
                <span className="compatibility-settings-section__proton-option-label">
                  <span className="compatibility-settings-section__proton-option-title">
                    {option.title}
                  </span>
                  <span className="compatibility-settings-section__proton-option-description">
                    {option.description}
                  </span>
                </span>
              }
              checked={form.defaultProtonPath === option.value}
              disabled={option.disabled}
              focusId={option.focusId}
              navigationOverrides={navigationOverrides}
              block
              onChange={() => {
                void updateCompatibilityPreferences({
                  defaultProtonPath: option.value || null,
                });
              }}
            />
          ),
        }))
      );
    }

    if (shouldRenderBehaviorSection) {
      nextItems.push(
        {
          focusId: COMPATIBILITY_GAMEMODE_FOCUS_ID,
          disabled: !canUseBehaviorSection || !gamemodeAvailable,
          render: (navigationOverrides: FocusOverrides) => (
            <div
              key={COMPATIBILITY_GAMEMODE_FOCUS_ID}
              className="compatibility-settings-section__behavior-item"
            >
              <Checkbox
                id={COMPATIBILITY_GAMEMODE_FOCUS_ID}
                label="Run with GameMode"
                secondaryText={
                  <>
                    Improves performance on supported Linux systems.{" "}
                    <a
                      className="compatibility-settings-section__helper-link"
                      href={GAMEMODE_SITE_URL}
                      target="_blank"
                      rel="noreferrer"
                      onClick={(event) => {
                        void handleOpenExternalLink(event, GAMEMODE_SITE_URL);
                      }}
                    >
                      Learn more
                    </a>
                    .
                  </>
                }
                checked={form.autoRunGamemode}
                disabled={!canUseBehaviorSection || !gamemodeAvailable}
                focusId={COMPATIBILITY_GAMEMODE_FOCUS_ID}
                navigationOverrides={navigationOverrides}
                block
                onChange={(checked) => {
                  void updateCompatibilityPreferences({
                    autoRunGamemode: checked,
                  });
                }}
              />
              {canUseBehaviorSection && !gamemodeAvailable ? (
                <p className="compatibility-settings-section__helper-note">
                  GameMode is not available in your PATH.
                </p>
              ) : null}
            </div>
          ),
        },
        {
          focusId: COMPATIBILITY_MANGOHUD_FOCUS_ID,
          disabled: !canUseBehaviorSection || !mangohudAvailable,
          render: (navigationOverrides: FocusOverrides) => (
            <div
              key={COMPATIBILITY_MANGOHUD_FOCUS_ID}
              className="compatibility-settings-section__behavior-item"
            >
              <Checkbox
                id={COMPATIBILITY_MANGOHUD_FOCUS_ID}
                label="Run with MangoHud"
                secondaryText={
                  <>
                    Shows performance metrics while you play.{" "}
                    <a
                      className="compatibility-settings-section__helper-link"
                      href={MANGOHUD_SITE_URL}
                      target="_blank"
                      rel="noreferrer"
                      onClick={(event) => {
                        void handleOpenExternalLink(event, MANGOHUD_SITE_URL);
                      }}
                    >
                      Learn more
                    </a>
                    .
                  </>
                }
                checked={form.autoRunMangohud}
                disabled={!canUseBehaviorSection || !mangohudAvailable}
                focusId={COMPATIBILITY_MANGOHUD_FOCUS_ID}
                navigationOverrides={navigationOverrides}
                block
                onChange={(checked) => {
                  void updateCompatibilityPreferences({
                    autoRunMangohud: checked,
                  });
                }}
              />
              {canUseBehaviorSection && !mangohudAvailable ? (
                <p className="compatibility-settings-section__helper-note">
                  MangoHud is not available in your PATH.
                </p>
              ) : null}
            </div>
          ),
        }
      );
    }

    if (shouldRenderCommonRedistSection) {
      nextItems.push({
        focusId: COMPATIBILITY_COMMON_REDIST_BUTTON_ID,
        disabled: !canUseCommonRedistSection || !canInstallCommonRedist,
        render: (navigationOverrides: FocusOverrides) => (
          <Button
            key={COMPATIBILITY_COMMON_REDIST_BUTTON_ID}
            className="compatibility-settings-section__common-redist-button"
            disabled={!canUseCommonRedistSection || !canInstallCommonRedist}
            loading={installingCommonRedist}
            focusId={COMPATIBILITY_COMMON_REDIST_BUTTON_ID}
            focusNavigationOverrides={navigationOverrides}
            onClick={() => {
              void handleInstallCommonRedist();
            }}
          >
            {installingCommonRedist
              ? "Installing Common Redist..."
              : "Install Common Redist"}
          </Button>
        ),
      });
    }

    return nextItems;
  }, [
    canInstallCommonRedist,
    canUseBehaviorSection,
    canUseCommonRedistSection,
    form.autoRunGamemode,
    form.autoRunMangohud,
    form.defaultProtonPath,
    gamemodeAvailable,
    handleInstallCommonRedist,
    installingCommonRedist,
    mangohudAvailable,
    protonOptions,
    shouldRenderCommonRedistSection,
    shouldRenderBehaviorSection,
    shouldRenderProtonSection,
    updateCompatibilityPreferences,
  ]);

  const activeItems = useMemo(
    () => items.filter((item) => !item.disabled),
    [items]
  );

  const navigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    return Object.fromEntries(
      activeItems.map((item, index) => {
        const previousItem = activeItems[index - 1];
        const nextItem = activeItems[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : SETTINGS_HEADER_RETURN_TARGET,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : { type: "block" },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [activeItems]);

  return (
    <div
      className={
        className
          ? `compatibility-settings-section ${className}`
          : "compatibility-settings-section"
      }
    >
      {shouldRenderProtonSection ? (
        <SettingsSection
          title="Default Proton Version"
          description="Choose which Proton version Hydra should use by default for compatible games."
        >
          <VerticalFocusGroup
            regionId={COMPATIBILITY_SECTION_REGION_ID}
            asChild
          >
            <div className="compatibility-settings-section__proton-options">
              {protonOptions.map((option) =>
                items
                  .find((item) => item.focusId === option.focusId)
                  ?.render(navigationOverridesByFocusId[option.focusId] ?? {})
              )}
            </div>
          </VerticalFocusGroup>
        </SettingsSection>
      ) : null}

      {shouldRenderBehaviorSection ? (
        <SettingsSection
          title="Behavior"
          description="Control which compatibility helpers Hydra should use when launching supported games."
        >
          <div className="compatibility-settings-section__content">
            {items
              .filter(
                (item) =>
                  item.focusId === COMPATIBILITY_GAMEMODE_FOCUS_ID ||
                  item.focusId === COMPATIBILITY_MANGOHUD_FOCUS_ID
              )
              .map((item) =>
                item.render(navigationOverridesByFocusId[item.focusId] ?? {})
              )}
          </div>
        </SettingsSection>
      ) : null}

      {shouldRenderCommonRedistSection ? (
        <SettingsSection
          title="Common Redist"
          description="Install the Microsoft redistributables required by some Windows games."
        >
          <div className="compatibility-settings-section__content">
            {items
              .filter(
                (item) => item.focusId === COMPATIBILITY_COMMON_REDIST_BUTTON_ID
              )
              .map((item) =>
                item.render(navigationOverridesByFocusId[item.focusId] ?? {})
              )}
          </div>
        </SettingsSection>
      ) : null}
    </div>
  );
}

import "./content.scss";

import { useEffect, useMemo, useState } from "react";

import { Checkbox, VerticalFocusGroup } from "../../components";
import { useUserPreferences } from "../../hooks";
import type { FocusOverrides } from "../../services";
import {
  CONTENT_ITEM_FOCUS_IDS,
  CONTENT_SECTION_REGION_ID,
  SETTINGS_HEADER_RETURN_TARGET,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface SettingsSectionProps {
  className?: string;
}

interface ContentForm {
  autoplayGameTrailers: boolean;
  disableNsfwAlert: boolean;
  showHiddenAchievementsDescription: boolean;
  enableSteamAchievements: boolean;
}

interface ContentItem {
  id: string;
  focusId: string;
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

const DEFAULT_FORM: ContentForm = {
  autoplayGameTrailers: true,
  disableNsfwAlert: false,
  showHiddenAchievementsDescription: false,
  enableSteamAchievements: false,
};

export function ContentSettingsSection({
  className,
}: Readonly<SettingsSectionProps>) {
  const userPreferences = useUserPreferences();
  const [form, setForm] = useState<ContentForm>(DEFAULT_FORM);

  useEffect(() => {
    if (!userPreferences) return;

    setForm({
      autoplayGameTrailers: userPreferences.autoplayGameTrailers ?? true,
      disableNsfwAlert: userPreferences.disableNsfwAlert ?? false,
      showHiddenAchievementsDescription:
        userPreferences.showHiddenAchievementsDescription ?? false,
      enableSteamAchievements: userPreferences.enableSteamAchievements ?? false,
    });
  }, [userPreferences]);

  const updateUserPreferences = async (values: Partial<ContentForm>) => {
    const nextForm = { ...form, ...values };
    setForm(nextForm);

    await globalThis.window.electron.updateUserPreferences(values);
  };

  const items = useMemo<ContentItem[]>(() => {
    return [
      {
        id: "autoplay-game-trailers",
        focusId: CONTENT_ITEM_FOCUS_IDS.autoplayGameTrailers,
        label: "Autoplay trailers on game page",
        checked: form.autoplayGameTrailers,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ autoplayGameTrailers: checked }),
