      {
        id: "disable-nsfw-alert",
        focusId: CONTENT_ITEM_FOCUS_IDS.disableNsfwAlert,
        label: "Disable NSFW alert",
        checked: form.disableNsfwAlert,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ disableNsfwAlert: checked }),
      },
      {
        id: "show-hidden-achievements-description",
        focusId: CONTENT_ITEM_FOCUS_IDS.showHiddenAchievementsDescription,
        label: "Show hidden achievement description",
        checked: form.showHiddenAchievementsDescription,
        onChange: (checked: boolean) =>
          void updateUserPreferences({
            showHiddenAchievementsDescription: checked,
          }),
      },
      {
        id: "enable-steam-achievements",
        focusId: CONTENT_ITEM_FOCUS_IDS.enableSteamAchievements,
        label: "Enable search for Steam achievements",
        checked: form.enableSteamAchievements,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ enableSteamAchievements: checked }),
      },
    ];
  }, [form]);

  const navigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    return Object.fromEntries(
      items.map((item, index) => {
        const previousItem = items[index - 1];
        const nextItem = items[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : SETTINGS_HEADER_RETURN_TARGET,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : {
                  type: "block",
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [items]);

  return (
    <div
      className={
        className
          ? `content-settings-section ${className}`
          : "content-settings-section"
      }
    >
      <SettingsSection
        title="Preferences"
        description="Choose how Hydra should handle trailers, content warnings, and achievement details."
      >
        <VerticalFocusGroup regionId={CONTENT_SECTION_REGION_ID} asChild>
          <div className="content-settings-section__content">
            {items.map((item) => (
              <Checkbox
                key={item.id}
                id={item.id}
                label={item.label}
                checked={item.checked}
                focusId={item.focusId}
                navigationOverrides={navigationOverridesByFocusId[item.focusId]}
                block
                onChange={item.onChange}
              />
            ))}
          </div>
        </VerticalFocusGroup>
      </SettingsSection>
    </div>
  );
}

import "./downloads-behavior-section.scss";

import { useEffect, useMemo, useState } from "react";

import { Checkbox, VerticalFocusGroup } from "../../components";
import { useUserPreferences } from "../../hooks";
import type { FocusOverrideTarget, FocusOverrides } from "../../services";
import {
  DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS,
  DOWNLOADS_BEHAVIOR_SECTION_REGION_ID,
  SETTINGS_HEADER_RETURN_TARGET,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface DownloadsBehaviorSectionProps {
  className?: string;
  lastItemDownTarget?: FocusOverrideTarget;
}

interface DownloadsBehaviorForm {
  seedAfterDownloadComplete: boolean;
  showDownloadSpeedInMegabytes: boolean;
  extractFilesByDefault: boolean;
  deleteArchiveFilesAfterExtractionByDefault: boolean;
  createStartMenuShortcut: boolean;
}

interface DownloadsBehaviorItem {
  id: string;
  focusId: string;
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

const DEFAULT_FORM: DownloadsBehaviorForm = {
  seedAfterDownloadComplete: false,
  showDownloadSpeedInMegabytes: false,
  extractFilesByDefault: true,
  deleteArchiveFilesAfterExtractionByDefault: false,
  createStartMenuShortcut: true,
};

export function DownloadsBehaviorSection({
  className,
  lastItemDownTarget,
}: Readonly<DownloadsBehaviorSectionProps>) {
  const userPreferences = useUserPreferences();
  const [form, setForm] = useState<DownloadsBehaviorForm>(DEFAULT_FORM);

  useEffect(() => {
    if (!userPreferences) return;

    setForm({
      seedAfterDownloadComplete:
        userPreferences.seedAfterDownloadComplete ?? false,
      showDownloadSpeedInMegabytes:
        userPreferences.showDownloadSpeedInMegabytes ?? false,
      extractFilesByDefault: userPreferences.extractFilesByDefault ?? true,
      deleteArchiveFilesAfterExtractionByDefault:
        userPreferences.deleteArchiveFilesAfterExtractionByDefault ?? false,
      createStartMenuShortcut: userPreferences.createStartMenuShortcut ?? true,
    });
  }, [userPreferences]);

  const isWindows = globalThis.window.electron.platform === "win32";

  const updateUserPreferences = async (
    values: Partial<DownloadsBehaviorForm>
  ) => {
    const nextForm = { ...form, ...values };
    setForm(nextForm);

    await globalThis.window.electron.updateUserPreferences(values);
  };

  const items = useMemo<DownloadsBehaviorItem[]>(() => {
    const baseItems: DownloadsBehaviorItem[] = [
      {
        id: "seed-after-download-complete",
        focusId: DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS.seedAfterDownloadComplete,
        label: "Seed after download complete",
        checked: form.seedAfterDownloadComplete,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ seedAfterDownloadComplete: checked }),
      },
      {
        id: "extract-files-by-default",
        focusId: DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS.extractFilesByDefault,
        label: "Extract files by default",
        checked: form.extractFilesByDefault,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ extractFilesByDefault: checked }),
      },
      {
        id: "show-download-speed-in-megabytes",
        focusId: DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS.showDownloadSpeedInMegabytes,
        label: "Show download speed in megabytes",
        checked: form.showDownloadSpeedInMegabytes,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ showDownloadSpeedInMegabytes: checked }),
      },
      {
        id: "delete-archive-files-after-extraction-by-default",
        focusId:
          DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS.deleteArchiveFilesAfterExtractionByDefault,
        label: "Delete archive files after extraction",
        checked: form.deleteArchiveFilesAfterExtractionByDefault,
        onChange: (checked: boolean) =>
          void updateUserPreferences({
            deleteArchiveFilesAfterExtractionByDefault: checked,
          }),
      },
    ];

    if (isWindows) {
      baseItems.push({
        id: "create-start-menu-shortcut",
        focusId: DOWNLOADS_BEHAVIOR_ITEM_FOCUS_IDS.createStartMenuShortcut,
        label: "Create shortcuts on download",
        checked: form.createStartMenuShortcut,
        onChange: (checked: boolean) =>
          void updateUserPreferences({ createStartMenuShortcut: checked }),
      });
    }

    return baseItems;
  }, [form, isWindows]);

  const navigationOverridesByFocusId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    return Object.fromEntries(
      items.map((item, index) => {
        const previousItem = items[index - 1];
        const nextItem = items[index + 1];

        return [
          item.focusId,
          {
            up: previousItem
              ? {
                  type: "item",
                  itemId: previousItem.focusId,
                }
              : SETTINGS_HEADER_RETURN_TARGET,
            down: nextItem
              ? {
                  type: "item",
                  itemId: nextItem.focusId,
                }
              : lastItemDownTarget
                ? lastItemDownTarget
                : undefined,
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [items, lastItemDownTarget]);

  return (
    <SettingsSection
      title="Behavior"
      description="Control how downloads behave by default."
      className={className}
    >
      <VerticalFocusGroup
        regionId={DOWNLOADS_BEHAVIOR_SECTION_REGION_ID}
        asChild
      >
        <div className="downloads-behavior-section__content">
          {items.map((item) => (
            <Checkbox
              key={item.id}
              id={item.id}
              label={item.label}
              checked={item.checked}
              focusId={item.focusId}
              navigationOverrides={navigationOverridesByFocusId[item.focusId]}
              block
              onChange={item.onChange}
            />
          ))}
        </div>
      </VerticalFocusGroup>
    </SettingsSection>
  );
}

import "./downloads-sources-section.scss";

import type { DownloadSource } from "@types";
import { DownloadSourceStatus } from "@shared";
import { orderBy } from "lodash-es";
import { ArrowsClockwiseIcon, TrashIcon } from "@phosphor-icons/react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";

import {
  Button,
  DownloadSourceCard,
  FocusItem,
  HorizontalFocusGroup,
  VerticalFocusGroup,
} from "../../components";
import { ConfirmationModal } from "../../components/modals";
import { getItemFocusTarget } from "../../helpers";
import {
  useBigPictureToast,
  useDate,
  useFormat,
  useNavigation,
} from "../../hooks";
import { BIG_PICTURE_SIDEBAR_ITEM_IDS } from "../../layout";
import type { FocusOverrides } from "../../services";
import {
  DOWNLOADS_SOURCES_ACTIONS_REGION_ID,
  DOWNLOADS_SOURCES_DELETE_ALL_BUTTON_ID,
  DOWNLOADS_SOURCES_EMPTY_STATE_ID,
  DOWNLOADS_SOURCES_SECTION_REGION_ID,
  DOWNLOADS_SOURCES_SYNC_BUTTON_ID,
  getLastDownloadsBehaviorItemFocusId,
  getDownloadsSourceRemoveButtonFocusId,
} from "./settings-navigation";
import { SettingsSection } from "./settings-section";

interface DownloadsSourcesSectionProps {
  className?: string;
}

function sortDownloadSources(downloadSources: DownloadSource[]) {
  return orderBy(downloadSources, "createdAt", "desc");
}

function isSyncingStatus(status: DownloadSourceStatus) {
  return (
    status === DownloadSourceStatus.PendingMatching ||
    status === DownloadSourceStatus.Matching
  );
}

function getStatusLabel(status: DownloadSourceStatus) {
  switch (status) {
    case DownloadSourceStatus.Matched:
      return "Up to Date";
    case DownloadSourceStatus.Failed:
      return "Error";
    case DownloadSourceStatus.PendingMatching:
    case DownloadSourceStatus.Matching:
      return "Syncing";
  }
}

function getStatusTone(status: DownloadSourceStatus) {
  switch (status) {
    case DownloadSourceStatus.Failed:
      return "error" as const;
    case DownloadSourceStatus.Matched:
      return "success" as const;
    default:
      return "default" as const;
  }
}

const SETTINGS_TOAST_OPTIONS = {
  fallbackVisual: "settings" as const,
};

export function DownloadsSourcesSection({
  className,
}: Readonly<DownloadsSourcesSectionProps>) {
  const { formatDateTime } = useDate();
  const { formatNumber } = useFormat();
  const { t } = useTranslation("big_picture");
  const { showSuccessToast, showErrorToast } = useBigPictureToast();
  const { setFocus, setFocusRegion } = useNavigation();
  const [downloadSources, setDownloadSources] = useState<DownloadSource[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isRemoving, setIsRemoving] = useState(false);
  const [showDeleteAllConfirmation, setShowDeleteAllConfirmation] =
    useState(false);

  const refreshDownloadSources = useCallback(async () => {
    const nextSources = await globalThis.window.electron.getDownloadSources();
    setDownloadSources(sortDownloadSources(nextSources));
  }, []);

  useEffect(() => {
    void refreshDownloadSources();
  }, [refreshDownloadSources]);

  useEffect(() => {
    const hasPendingSource = downloadSources.some((downloadSource) =>
      isSyncingStatus(downloadSource.status)
    );

    if (!hasPendingSource || !downloadSources.length) {
      return;
    }

    const intervalId = globalThis.window.setInterval(() => {
      void refreshDownloadSources();
    }, 5000);

    return () => {
      globalThis.window.clearInterval(intervalId);
    };
  }, [downloadSources, refreshDownloadSources]);

  const isBusy = isSyncing || isRemoving;
  const hasSources = downloadSources.length > 0;
  const isWindows = globalThis.window.electron.platform === "win32";
  const firstRemoveButtonFocusId = downloadSources[0]
    ? getDownloadsSourceRemoveButtonFocusId(downloadSources[0].id)
    : null;
  const lastBehaviorFocusId = getLastDownloadsBehaviorItemFocusId(isWindows);

  const actionNavigationOverrides: FocusOverrides = useMemo(
    () => ({
      up: {
        type: "item",
        itemId: lastBehaviorFocusId,
      },
      down: firstRemoveButtonFocusId
        ? {
            type: "item",
            itemId: firstRemoveButtonFocusId,
          }
        : {
            type: "block",
          },
    }),
    [firstRemoveButtonFocusId, lastBehaviorFocusId]
  );

  const syncButtonNavigationOverrides: FocusOverrides = useMemo(
    () => ({
      ...actionNavigationOverrides,
      left: getItemFocusTarget(BIG_PICTURE_SIDEBAR_ITEM_IDS.settings),
      right: {
        type: "item",
        itemId: DOWNLOADS_SOURCES_DELETE_ALL_BUTTON_ID,
      },
    }),
    [actionNavigationOverrides]
  );

  const deleteAllButtonNavigationOverrides: FocusOverrides = useMemo(
    () => ({
      ...actionNavigationOverrides,
      left: {
        type: "item",
        itemId: DOWNLOADS_SOURCES_SYNC_BUTTON_ID,
      },
      right: {
        type: "block",
      },
    }),
    [actionNavigationOverrides]
  );

  const removeButtonNavigationOverridesBySourceId = useMemo<
    Record<string, FocusOverrides>
  >(() => {
    return Object.fromEntries(
      downloadSources.map((downloadSource, index) => {
        const previousSource = downloadSources[index - 1];
        const nextSource = downloadSources[index + 1];

        return [
          downloadSource.id,
          {
            up: previousSource
              ? {
                  type: "item",
                  itemId: getDownloadsSourceRemoveButtonFocusId(
                    previousSource.id
                  ),
                }
              : {
                  type: "region",
                  regionId: DOWNLOADS_SOURCES_ACTIONS_REGION_ID,
                  entryDirection: "up",
                  preferRememberedFocus: true,
                },
            down: nextSource
              ? {
                  type: "item",
                  itemId: getDownloadsSourceRemoveButtonFocusId(nextSource.id),
                }
              : {
                  type: "block",
                },
          } satisfies FocusOverrides,
        ];
      })
    );
  }, [downloadSources]);

  const handleSync = useCallback(async () => {
    setIsSyncing(true);

    try {
      await globalThis.window.electron.syncDownloadSources();
      await refreshDownloadSources();
      showSuccessToast("Download sources synced successfully", {
        ...SETTINGS_TOAST_OPTIONS,
        message: `Last synced on ${formatDateTime(new Date())}.`,
      });
    } catch {
      showErrorToast("Failed to sync download sources", SETTINGS_TOAST_OPTIONS);
    } finally {
      setIsSyncing(false);
    }
  }, [refreshDownloadSources, showErrorToast, showSuccessToast]);

  const handleRemoveSource = useCallback(
    async (downloadSourceId: string) => {
      const removedSource = downloadSources.find(
        (downloadSource) => downloadSource.id === downloadSourceId
      );
      const removedDownloadOptionsLabel = removedSource
        ? t("download_options_unavailable", {
            count: removedSource.downloadCount,
            formattedCount: formatNumber(removedSource.downloadCount),
          })
        : undefined;
      const currentIndex = downloadSources.findIndex(
        (downloadSource) => downloadSource.id === downloadSourceId
      );
      const nextSource = downloadSources[currentIndex + 1];
      const previousSource = downloadSources[currentIndex - 1];
      const nextFocusId = nextSource
        ? getDownloadsSourceRemoveButtonFocusId(nextSource.id)
        : previousSource
          ? getDownloadsSourceRemoveButtonFocusId(previousSource.id)
          : null;

      setIsRemoving(true);

      try {
        await globalThis.window.electron.removeDownloadSource(
          false,
          downloadSourceId
        );
        await refreshDownloadSources();
        showSuccessToast(
          removedSource
            ? `${removedSource.name} was removed`
            : "Download source removed",
          removedSource
            ? {
                ...SETTINGS_TOAST_OPTIONS,
                message: removedDownloadOptionsLabel,
              }
            : SETTINGS_TOAST_OPTIONS
        );
        globalThis.window.requestAnimationFrame(() => {
          if (nextFocusId) {
            setFocus(nextFocusId);
            return;
          }

          const regionFocusId = setFocusRegion(
            DOWNLOADS_SOURCES_ACTIONS_REGION_ID,
            "up",
            {
              preferRememberedFocus: true,
            }
          );

          if (!regionFocusId) {
            setFocus(lastBehaviorFocusId);
          }
        });
      } catch {
        showErrorToast(
          "Failed to remove download source",
          SETTINGS_TOAST_OPTIONS
        );
      } finally {
        setIsRemoving(false);
      }
    },
    [
      downloadSources,
      formatNumber,
      lastBehaviorFocusId,
      refreshDownloadSources,
      setFocus,
      setFocusRegion,
      showErrorToast,
      showSuccessToast,
      t,
    ]
  );

  const handleDeleteAllSources = useCallback(async () => {
    const removedSourceCount = downloadSources.length;
    const removedDownloadOptionCount = downloadSources.reduce(
      (total, downloadSource) => total + downloadSource.downloadCount,
      0
    );
    const removedSourcesLabel = t("download_sources_removed", {
      count: removedSourceCount,
    });
    const removedDownloadOptionsLabel = t("download_options_unavailable", {
      count: removedDownloadOptionCount,
      formattedCount: formatNumber(removedDownloadOptionCount),
    });

    setIsRemoving(true);

    try {
      await globalThis.window.electron.removeDownloadSource(true);
      await refreshDownloadSources();
      showSuccessToast(removedSourcesLabel, {
        ...SETTINGS_TOAST_OPTIONS,
        message: removedDownloadOptionsLabel,
      });
      setShowDeleteAllConfirmation(false);
    } catch {
      showErrorToast(
        "Failed to remove download sources",
        SETTINGS_TOAST_OPTIONS
      );
    } finally {
      setIsRemoving(false);
    }
  }, [
    downloadSources.length,
    downloadSources,
    formatNumber,
    refreshDownloadSources,
    showErrorToast,
    showSuccessToast,
    t,
  ]);

  return (
    <>
      <SettingsSection
        title="Sources"
        description="Hydra will fetch the download links from these sources. The source URL must be a direct link to a .json file containing the download the links."
        className={className}
      >
        <VerticalFocusGroup
          regionId={DOWNLOADS_SOURCES_SECTION_REGION_ID}
          className="downloads-sources-section__content"
        >
          <HorizontalFocusGroup
            regionId={DOWNLOADS_SOURCES_ACTIONS_REGION_ID}
            className="downloads-sources-section__actions"
            navigationOverrides={actionNavigationOverrides}
          >
            <div className="downloads-sources-section__actions-left">
              <Button
                variant="secondary"
                size="small"
                icon={<ArrowsClockwiseIcon size={18} />}
                focusId={DOWNLOADS_SOURCES_SYNC_BUTTON_ID}
                focusNavigationOverrides={syncButtonNavigationOverrides}
                loading={isSyncing}
                disabled={!hasSources || isRemoving}
                onClick={() => {
                  void handleSync();
                }}
              >
                Sync All
              </Button>
            </div>

            <div className="downloads-sources-section__actions-right">
              <Button
                variant="danger"
                size="small"
                icon={<TrashIcon size={18} />}
                focusId={DOWNLOADS_SOURCES_DELETE_ALL_BUTTON_ID}
                focusNavigationOverrides={deleteAllButtonNavigationOverrides}
                disabled={!hasSources || isBusy}
                onClick={() => {
                  setShowDeleteAllConfirmation(true);
                }}
              >
                Delete All
              </Button>
            </div>
          </HorizontalFocusGroup>

          {hasSources ? (
            <div className="downloads-sources-section__list">
              {downloadSources.map((downloadSource) => {
                const downloadCountLabel = t("download_options_count", {
                  count: downloadSource.downloadCount,
                  formattedCount: formatNumber(downloadSource.downloadCount),
                });

                return (
                  <DownloadSourceCard
                    key={downloadSource.id}
                    name={downloadSource.name}
                    countLabel={downloadCountLabel}
                    statusLabel={getStatusLabel(downloadSource.status)}
                    statusTone={getStatusTone(downloadSource.status)}
                    url={downloadSource.url}
                    removeButtonFocusId={getDownloadsSourceRemoveButtonFocusId(
                      downloadSource.id
                    )}
                    removeButtonNavigationOverrides={
                      removeButtonNavigationOverridesBySourceId[
                        downloadSource.id
                      ]
                    }
                    removeDisabled={isBusy}
                    onRemove={() => {
                      void handleRemoveSource(downloadSource.id);
                    }}
                  />
                );
              })}
            </div>
          ) : (
            <FocusItem
              id={DOWNLOADS_SOURCES_EMPTY_STATE_ID}
              asChild
              navigationOverrides={{
                up: {
                  type: "item",
                  itemId: lastBehaviorFocusId,
                },
                down: {
                  type: "block",
                },
              }}
            >
              <div className="downloads-sources-section__empty-state">
                <p className="downloads-sources-section__empty">
                  No sources available.
                </p>
              </div>
            </FocusItem>
          )}
        </VerticalFocusGroup>
      </SettingsSection>

      <ConfirmationModal
        visible={showDeleteAllConfirmation}
        title="Delete All Sources"
        description="This will remove every configured download source from Hydra."
        confirmLabel="Delete All"
        danger
        loading={isRemoving}
        onClose={() => {
