import fs from "node:fs/promises";
import { registerEvent } from "../register-event";

interface DriveInfo {
  root: string;
  label: string;
  free: number;
  total: number;
}

const DRIVE_SEPARATOR = String.fromCharCode(92);
const DRIVE_LETTERS = Array.from({ length: 26 }, (_, i) =>
  String.fromCharCode(65 + i)
);
const LINUX_IGNORED_FS_TYPES = new Set([
  "proc",
  "sysfs",
  "tmpfs",
  "devtmpfs",
  "devpts",
  "overlay",
  "squashfs",
  "nsfs",
  "cgroup",
  "cgroup2",
  "pstore",
  "bpf",
  "tracefs",
  "securityfs",
  "configfs",
  "debugfs",
  "mqueue",
  "hugetlbfs",
  "fusectl",
  "ramfs",
  "autofs",
  "binfmt_misc",
]);

function getDriveRoot(letter: string): string {
  return `${letter}:${DRIVE_SEPARATOR}`;
}

async function getDriveInfo(root: string): Promise<DriveInfo | null> {
  if (typeof (fs as any).statfs !== "function") return null;

  try {
    const stats = await (fs as any).statfs(root);
    const total = stats.blocks * stats.bsize;
    const free = stats.bavail * stats.bsize;

    if (total <= 0) return null;

    return {
      root,
      label: root.slice(0, 2),
      free: Math.max(0, free),
      total,
    };
  } catch {
    return null;
  }
}

async function queryWindowsDrives(): Promise<DriveInfo[]> {
  const driveChecks = DRIVE_LETTERS.map((letter) =>
    getDriveInfo(getDriveRoot(letter))
  );
  const drives = await Promise.all(driveChecks);

  return drives.filter((drive): drive is DriveInfo => drive !== null);
}

function decodeLinuxMountPath(value: string): string {
  return value
    .replaceAll("\\040", " ")
    .replaceAll("\\011", "\t")
    .replaceAll("\\012", "\n")
    .replaceAll("\\134", DRIVE_SEPARATOR);
}

async function getLinuxMountPoints(): Promise<string[]> {
  const mounts = await fs.readFile("/proc/mounts", "utf8").catch(() => "");
  if (!mounts.trim()) return ["/"];

  const mountPoints = new Set<string>();

  for (const line of mounts.split(/\r?\n/)) {
    if (!line.trim()) continue;

    const [source = "", target = "", fsType = ""] = line.split(" ");
    if (!target || LINUX_IGNORED_FS_TYPES.has(fsType)) continue;

    const isDeviceMount = source.startsWith("/dev/");
    const isUserSpaceFs = fsType.startsWith("fuse.");
    if (!isDeviceMount && !isUserSpaceFs) continue;

    mountPoints.add(decodeLinuxMountPath(target));
  }

  if (mountPoints.size === 0) mountPoints.add("/");
  return Array.from(mountPoints);
}

async function queryLinuxDrives(): Promise<DriveInfo[]> {
  const mountPoints = await getLinuxMountPoints();
  const driveChecks = mountPoints.map((mountPoint) => getDriveInfo(mountPoint));
  const drives = await Promise.all(driveChecks);

  return drives
    .filter((drive): drive is DriveInfo => drive !== null)
    .map((drive) => ({ ...drive, label: drive.root }));
}

const getAvailableDrives = async (): Promise<DriveInfo[]> => {
  console.log("getAvailableDrives called, platform:", process.platform);

  try {
    if (process.platform === "win32") {
      const drives = await queryWindowsDrives();
      console.log("Parsed drives:", drives.length, "drives found");
      return drives;
    }

    if (process.platform === "linux") {
      const drives = await queryLinuxDrives();
      console.log("Parsed drives:", drives.length, "drives found");
      return drives;
    }

    return [];
  } catch (error) {
    console.error("Failed to fetch drives:", error);
    return [];
  }
};

registerEvent("getAvailableDrives", getAvailableDrives);

import path from "node:path";
import fs from "node:fs/promises";
import { createReadStream, createWriteStream } from "node:fs";
import { registerEvent } from "../register-event";
import { gamesSublevel, downloadsSublevel, levelKeys } from "@main/level";
import { updateGameExecutablePath } from "@main/helpers/update-executable-path";
import { findGameRootFromExe } from "../helpers/find-game-root";
import { getDirectorySize } from "../helpers/get-directory-size";
import { WindowManager } from "@main/services/window-manager";
import type { GameShop, LibraryGame } from "@types";

// ── Helpers ─────────────────────────────────────────────────────────────────
function send(
  event: string,
  shop: GameShop,
  objectId: string,
  ...args: unknown[]
) {
  WindowManager.mainWindow?.webContents.send(event, shop, objectId, ...args);
}

// ── State ───────────────────────────────────────────────────────────────────
const activeTransfers = new Map<
  string,
  {
    cancelled: boolean;
    currentStreams: Set<{ destroy(): void }>;
    pendingRejects: Array<(error: Error) => void>;
  }
>();

// ── Steam‑style copy engine ─────────────────────────────────────────────────
class SteamCopyEngine {
  private bytesCopied = 0;
  private readonly totalSize: number;
  private readonly startTime: number;
  private lastReportTime = 0;
  private readonly REPORT_INTERVAL = 100;
  private readonly BLOCK_SIZE = 1024 * 1024;
  private readonly CONCURRENCY = 8; //4 default - 8 performance/faster

  constructor(
    private readonly id: string,
    private readonly shop: GameShop,
    private readonly objectId: string,
    totalSize: number
  ) {
    this.totalSize = totalSize;
    this.startTime = Date.now();
  }

  private reportProgress() {
    const now = Date.now();
    if (now - this.lastReportTime < this.REPORT_INTERVAL) return;
    this.lastReportTime = now;

    const elapsedSec = (now - this.startTime) / 1000;
    const speedMBps =
      elapsedSec > 0 ? this.bytesCopied / elapsedSec / 1_048_576 : 0;
    const remaining = this.totalSize - this.bytesCopied;
    const etaSeconds = speedMBps > 0 ? remaining / (speedMBps * 1_048_576) : 0;
    const progress = this.bytesCopied / Math.max(this.totalSize, 1);

    send("on-game-transfer-progress", this.shop, this.objectId, progress, {
      speed: Math.max(0, speedMBps),
      eta: Math.ceil(etaSeconds),
      transferred: this.bytesCopied,
      total: this.totalSize,
    });
  }

  private addBytes(bytes: number) {
    this.bytesCopied += bytes;
    this.reportProgress();
  }

  async moveGame(src: string, dest: string): Promise<void> {
    await fs.mkdir(dest, { recursive: true });
    await this.copyDirectory(src, dest);
    await fs.rm(src, { recursive: true, force: true }).catch(() => {});
  }

  private async copyDirectory(srcDir: string, destDir: string): Promise<void> {
    const entries = await fs.readdir(srcDir, { withFileTypes: true });

    const files = entries.filter((e) => e.isFile());
    const dirs = entries.filter((e) => e.isDirectory());

    for (let i = 0; i < files.length; i += this.CONCURRENCY) {
      await this.checkCancelled();

      const batch = files.slice(i, i + this.CONCURRENCY);
      await Promise.all(
        batch.map((file) =>
          this.copyFileWithProgress(
            path.join(srcDir, file.name),
            path.join(destDir, file.name)
          )
        )
      );
    }

    for (const dir of dirs) {
      await this.checkCancelled();

      const srcPath = path.join(srcDir, dir.name);
      const destPath = path.join(destDir, dir.name);
      await fs.mkdir(destPath, { recursive: true });
      await this.copyDirectory(srcPath, destPath);
    }
  }

  private async checkCancelled(): Promise<void> {
    const state = activeTransfers.get(this.id);
    if (state?.cancelled) throw new Error("cancelled");
  }

  private copyFileWithProgress(
    srcFile: string,
    destFile: string
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const state = activeTransfers.get(this.id);

      if (!state || state.cancelled) {
        return reject(new Error("cancelled"));
      }

      state.pendingRejects.push(reject);

      const readStream = createReadStream(srcFile, {
        highWaterMark: this.BLOCK_SIZE,
      });
      const writeStream = createWriteStream(destFile);

      const streamRef = {
        destroy() {
          readStream.destroy();
          writeStream.destroy();
        },
      };
      state.currentStreams.add(streamRef);

      const cleanup = () => {
        const idx = state.pendingRejects.indexOf(reject);
        if (idx !== -1) state.pendingRejects.splice(idx, 1);
        state.currentStreams.delete(streamRef);
      };

      readStream.on("data", (chunk: string | Buffer) => {
        this.addBytes(Buffer.byteLength(chunk));
      });

      readStream.on("close", () => {
        if (!state.cancelled) return;
        cleanup();
        reject(new Error("cancelled"));
      });

      readStream.on("error", (err) => {
        cleanup();
        reject(err);
      });
      writeStream.on("error", (err) => {
        cleanup();
        reject(err);
      });
      writeStream.on("finish", () => {
        cleanup();
        resolve();
      });

      readStream.pipe(writeStream);
    });
  }
}

// ── Helper functions for transfer validation ────────────────────────────────
interface GameWithExecutable extends LibraryGame {
  executablePath: string;
}

async function validateGameExists(
  shop: GameShop,
  objectId: string
): Promise<GameWithExecutable | null> {
  const gameKey = levelKeys.game(shop, objectId);
  try {
    const game = (await gamesSublevel.get(gameKey)) as LibraryGame | undefined;
    if (game?.executablePath) {
      return game as GameWithExecutable;
    }
    return null;
  } catch {
    return null;
  }
}

async function validateGameRoot(
  game: GameWithExecutable
): Promise<
  { valid: true; gameRoot: string } | { valid: false; error: string }
> {
  const gameRoot = await findGameRootFromExe(game.executablePath).catch(
    () => null
  );
  if (!gameRoot) {
    return { valid: false, error: "Cannot determine game root folder" };
  }

  return { valid: true, gameRoot };
}

async function validateDestination(
  gameRoot: string,
  _destParent: string,
  targetRoot: string
) {
  const normalizePath = (value: string) =>
    process.platform === "win32" ? value.toLowerCase() : value;

  const resolvedGameRoot = normalizePath(path.resolve(gameRoot));
  const resolvedTargetRoot = normalizePath(path.resolve(targetRoot));

  if (resolvedGameRoot === resolvedTargetRoot) {
    return { valid: false, error: "Game is already in this location" };
  }

  if (resolvedTargetRoot.startsWith(`${resolvedGameRoot}${path.sep}`)) {
    return { valid: false, error: "Destination is inside source folder" };
  }

  try {
    await fs.stat(targetRoot);
    return {
      valid: false,
      error: "Destination folder already exists",
    };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      return {
        valid: false,
        error: "Cannot access destination folder",
      };
    }
  }

  return { valid: true };
}

async function checkDiskSpace(destParent: string, requiredSize: number) {
  try {
    if (typeof (fs as any).statfs === "function") {
      const stats = await (fs as any).statfs(destParent);
      const available = stats.bfree * stats.bsize;
      if (available < requiredSize) {
        return {
          hasSpace: false,
          error: "not_enough_space" as const,
          needed: requiredSize,
          available,
        };
      }
    }
  } catch {
    // Proceed without check if unavailable
  }

  return { hasSpace: true };
}

async function updateDatabaseAfterTransfer(
  game: GameWithExecutable,
  gameKey: string,
  newExePath: string,
  gameSize: number,
  targetRoot: string
) {
  const installedSizeInBytes = game.installedSizeInBytes ?? gameSize;

  await gamesSublevel.put(gameKey, {
    ...updateGameExecutablePath(game, newExePath),
    installedSizeInBytes,
  });

  const download = await downloadsSublevel.get(gameKey).catch(() => null);
  if (download) {
    await downloadsSublevel
      .put(gameKey, {
        ...download,
        downloadPath: path.dirname(targetRoot),
        folderName: path.basename(targetRoot),
      })
      .catch(() => {});
  }
}

async function cleanupOnError(id: string, targetRoot: string) {
  await fs.rm(targetRoot, { recursive: true, force: true }).catch(() => {});
  activeTransfers.delete(id);
}

// ── MAIN TRANSFER EVENT ─────────────────────────────────────────────────────
registerEvent(
  "transferGameFiles",
  async (_event, shop: GameShop, objectId: string, destParent: string) => {
    const id = `${shop}:${objectId}`;
    activeTransfers.set(id, {
      cancelled: false,
      currentStreams: new Set(),
      pendingRejects: [],
    });

    // Validate game exists and has executable path
    const game = await validateGameExists(shop, objectId);
    if (!game) {
      activeTransfers.delete(id);
      return { ok: false, error: "Game not found or has no executable path" };
    }

    // Validate game root
    const rootValidation = await validateGameRoot(game);
    if (!rootValidation.valid) {
      activeTransfers.delete(id);
      return { ok: false, error: rootValidation.error };
    }
    const gameRoot: string = rootValidation.gameRoot;

    const folderName = path.basename(gameRoot);
    const targetRoot = path.join(destParent, folderName);

    // Validate destination
    const destValidation = await validateDestination(
      gameRoot,
      destParent,
      targetRoot
    );
    if (!destValidation.valid) {
      activeTransfers.delete(id);
      return { ok: false, error: destValidation.error };
    }

    // Send initial progress
    send("on-game-transfer-progress", shop, objectId, 0, {
      speed: 0,
      eta: 0,
      transferred: 0,
      total: 0,
    });

    const gameSize = await getDirectorySize(gameRoot);

    // Check disk space
    const spaceCheck = await checkDiskSpace(destParent, gameSize);
    if (!spaceCheck.hasSpace) {
      activeTransfers.delete(id);
      return {
        ok: false,
        error: spaceCheck.error,
        needed: spaceCheck.needed,
        available: spaceCheck.available,
      };
    }

    await fs.mkdir(destParent, { recursive: true });

    const engine = new SteamCopyEngine(id, shop, objectId, gameSize);

    try {
      await engine.moveGame(gameRoot, targetRoot);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      await cleanupOnError(id, targetRoot);

      if (msg === "cancelled") {
        send("on-game-transfer-cancelled", shop, objectId);
        return { ok: false, error: "Transfer cancelled" };
      }

      send("on-game-transfer-error", shop, objectId, msg);
      return { ok: false, error: msg };
    }

    const relExe = path.relative(gameRoot, game.executablePath);
    const newExePath = path.join(targetRoot, relExe);
    const gameKey = levelKeys.game(shop, objectId);

    try {
      await updateDatabaseAfterTransfer(
        game,
        gameKey,
        newExePath,
        gameSize,
        targetRoot
      );
    } catch {
      activeTransfers.delete(id);
      send(
        "on-game-transfer-error",
        shop,
        objectId,
        "Failed to update database"
      );
      return { ok: false, error: "Failed to update database" };
    }

    activeTransfers.delete(id);
    send("on-game-transfer-complete", shop, objectId, newExePath);
    return { ok: true, newExePath };
  }
);

// ── CANCEL ────────────────────────────────────────────────────────────────────
registerEvent(
  "cancelGameTransfer",
  async (_e, shop: GameShop, objectId: string) => {
    const s = activeTransfers.get(`${shop}:${objectId}`);
    if (s) {
      s.cancelled = true;
      s.currentStreams.forEach((stream) => stream.destroy());
      s.currentStreams.clear();
      s.pendingRejects.forEach((reject) => reject(new Error("cancelled")));
      s.pendingRejects = [];
    }
  }
);

import { ipcMain } from "electron";

export const registerEvent = (
  name: string,
  listener: (event: Electron.IpcMainInvokeEvent, ...args: any[]) => any
) => {
  ipcMain.handle(name, async (event: Electron.IpcMainInvokeEvent, ...args) => {
    return Promise.resolve(listener(event, ...args)).then((result) => {
      if (!result) return result;
      return JSON.parse(JSON.stringify(result));
    });
  });
};

import { Cracker } from "@shared";
import { UnlockedAchievement } from "@types";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { achievementsLogger } from "../logger";

export const parseAchievementFile = (
  filePath: string,
  type: Cracker
): UnlockedAchievement[] => {
  if (!existsSync(filePath)) return [];

  try {
    if (type == Cracker.codex) {
      const parsed = iniParse(filePath);
      return processDefault(parsed);
    }

    if (type == Cracker.rune) {
      const parsed = iniParse(filePath);
      return processDefault(parsed);
    }

    if (type === Cracker.onlineFix) {
      const parsed = iniParse(filePath);
      return processOnlineFix(parsed);
    }

    if (type === Cracker.goldberg) {
      const parsed = jsonParse(filePath);
      return processGoldberg(parsed);
    }

    if (type == Cracker.userstats) {
      const parsed = iniParse(filePath);
      return processUserStats(parsed);
    }

    if (type == Cracker.rld) {
      const parsed = iniParse(filePath);
      return processRld(parsed);
    }

    if (type === Cracker.skidrow) {
      const parsed = iniParse(filePath);
      return processSkidrow(parsed);
    }

    if (type === Cracker._3dm) {
      const parsed = iniParse(filePath);
      return process3DM(parsed);
    }

    if (type === Cracker.flt) {
      const achievements = readdirSync(filePath);

      return achievements.map((achievement) => {
        return {
          name: achievement,
          unlockTime: Date.now(),
        };
      });
    }

    if (type === Cracker.creamAPI) {
      const parsed = iniParse(filePath);
      return processCreamAPI(parsed);
    }

    if (type === Cracker.empress) {
      const parsed = jsonParse(filePath);
      return processGoldberg(parsed);
    }

    if (type === Cracker.razor1911) {
      return processRazor1911(filePath);
    }

    if (type === Cracker.Steam) {
      const parsed = jsonParse(filePath);
      return processSteamCacheAchievement(parsed);
    }

    achievementsLogger.log(
      `Unprocessed ${type} achievements found on ${filePath}`
    );
    return [];
  } catch (err) {
    achievementsLogger.error(`Error parsing ${type} - ${filePath}`, err);
    return [];
  }
};

const iniParse = (filePath: string) => {
  const fileContent = readFileSync(filePath, "utf-8");

  const lines =
    fileContent.charCodeAt(0) === 0xfeff
      ? fileContent.slice(1).split(/[\r\n]+/)
      : fileContent.split(/[\r\n]+/);

  let objectName = "";
  const object: Record<string, Record<string, string | number>> = {};

  for (const line of lines) {
    if (line.startsWith("###") || !line.length) continue;

    if (line.startsWith("[") && line.endsWith("]")) {
      objectName = line.slice(1, -1);
      object[objectName] = {};
    } else {
      const [name, ...value] = line.split("=");
      object[objectName][name.trim()] = value.join("=").trim();
    }
  }

  return object;
};

const jsonParse = (filePath: string) => {
  return JSON.parse(readFileSync(filePath, "utf-8"));
};

const processRazor1911 = (filePath: string): UnlockedAchievement[] => {
  const fileContent = readFileSync(filePath, "utf-8");

  const lines =
    fileContent.charCodeAt(0) === 0xfeff
      ? fileContent.slice(1).split(/[\r\n]+/)
      : fileContent.split(/[\r\n]+/);

  const achievements: UnlockedAchievement[] = [];
  for (const line of lines) {
    if (!line.length) continue;

    const [name, unlocked, unlockTime] = line.split(" ");
    if (unlocked === "1") {
      achievements.push({
        name,
        unlockTime: Number(unlockTime) * 1000,
      });
    }
  }

  return achievements;
};

const processOnlineFix = (unlockedAchievements: any): UnlockedAchievement[] => {
  const parsedUnlockedAchievements: UnlockedAchievement[] = [];

  for (const achievement of Object.keys(unlockedAchievements)) {
    const unlockedAchievement = unlockedAchievements[achievement];

    if (unlockedAchievement?.achieved == "true") {
      parsedUnlockedAchievements.push({
        name: achievement,
        unlockTime: unlockedAchievement.timestamp * 1000,
      });
    } else if (unlockedAchievement?.Achieved == "true") {
      const unlockTime = unlockedAchievement.TimeUnlocked;

      parsedUnlockedAchievements.push({
        name: achievement,
        unlockTime:
          unlockTime.length === 7
            ? unlockTime * 1000 * 1000
            : unlockTime * 1000,
      });
    }
  }

  return parsedUnlockedAchievements;
};

const processCreamAPI = (unlockedAchievements: any): UnlockedAchievement[] => {
  const parsedUnlockedAchievements: UnlockedAchievement[] = [];

  for (const achievement of Object.keys(unlockedAchievements)) {
    const unlockedAchievement = unlockedAchievements[achievement];

    if (unlockedAchievement?.achieved == "true") {
      const unlockTime = unlockedAchievement.unlocktime;
      parsedUnlockedAchievements.push({
        name: achievement,
        unlockTime:
          unlockTime.length === 7
            ? unlockTime * 1000 * 1000
            : unlockTime * 1000,
      });
    }
  }

  return parsedUnlockedAchievements;
};

const processSkidrow = (unlockedAchievements: any): UnlockedAchievement[] => {
  const parsedUnlockedAchievements: UnlockedAchievement[] = [];
  const achievements = unlockedAchievements["Achievements"];

  for (const achievement of Object.keys(achievements)) {
    const unlockedAchievement = achievements[achievement].split("@");

    if (unlockedAchievement[0] === "1") {
      parsedUnlockedAchievements.push({
        name: achievement,
        unlockTime: unlockedAchievement[unlockedAchievement.length - 1] * 1000,
      });
    }
  }

  return parsedUnlockedAchievements;
};

const processGoldberg = (unlockedAchievements: any): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  if (Array.isArray(unlockedAchievements)) {
    for (const achievement of unlockedAchievements) {
      if (achievement?.earned) {
        newUnlockedAchievements.push({
          name: achievement.name,
          unlockTime: achievement.earned_time * 1000,
        });
      }
    }

    return newUnlockedAchievements;
  }

  for (const achievement of Object.keys(unlockedAchievements)) {
    const unlockedAchievement = unlockedAchievements[achievement];

    if (unlockedAchievement?.earned) {
      newUnlockedAchievements.push({
        name: achievement,
        unlockTime: unlockedAchievement.earned_time * 1000,
      });
    }
  }
  return newUnlockedAchievements;
};

const processSteamCacheAchievement = (
  unlockedAchievements: any[]
): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  const achievementIndex = unlockedAchievements.findIndex(
    (element) => element[0] === "achievements"
  );

  if (achievementIndex === -1) {
    achievementsLogger.info("No achievements found in Steam cache file");
    return [];
  }

  const unlockedAchievementsData =
    unlockedAchievements[achievementIndex][1]["data"]["vecHighlight"];

  for (const achievement of unlockedAchievementsData) {
    if (achievement.bAchieved) {
      newUnlockedAchievements.push({
        name: achievement.strID,
        unlockTime: achievement.rtUnlocked * 1000,
      });
    }
  }

  return newUnlockedAchievements;
};

const process3DM = (unlockedAchievements: any): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  const achievements = unlockedAchievements["State"];
  const times = unlockedAchievements["Time"];

  for (const achievement of Object.keys(achievements)) {
    if (achievements[achievement] == "0101") {
      const time = times[achievement];

      newUnlockedAchievements.push({
        name: achievement,
        unlockTime:
          new DataView(
            new Uint8Array(Buffer.from(time.toString(), "hex")).buffer
          ).getUint32(0, true) * 1000,
      });
    }
  }

  return newUnlockedAchievements;
};

const processDefault = (unlockedAchievements: any): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  for (const achievement of Object.keys(unlockedAchievements)) {
    const unlockedAchievement = unlockedAchievements[achievement];

    if (unlockedAchievement?.Achieved == "1") {
      newUnlockedAchievements.push({
        name: achievement,
        unlockTime: unlockedAchievement.UnlockTime * 1000,
      });
    }
  }

  return newUnlockedAchievements;
};

const processRld = (unlockedAchievements: any): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  for (const achievement of Object.keys(unlockedAchievements)) {
    if (achievement === "Steam") continue;

    const unlockedAchievement = unlockedAchievements[achievement];

    if (unlockedAchievement?.State) {
      const unlocked = new DataView(
        new Uint8Array(
          Buffer.from(unlockedAchievement.State.toString(), "hex")
        ).buffer
      ).getUint32(0, true);

      if (unlocked === 1) {
        newUnlockedAchievements.push({
          name: achievement,
          unlockTime:
            new DataView(
              new Uint8Array(
                Buffer.from(unlockedAchievement.Time.toString(), "hex")
              ).buffer
            ).getUint32(0, true) * 1000,
        });
      }
    }
  }

  return newUnlockedAchievements;
};

const processUserStats = (unlockedAchievements: any): UnlockedAchievement[] => {
  const newUnlockedAchievements: UnlockedAchievement[] = [];

  const achievements = unlockedAchievements["ACHIEVEMENTS"];

  if (!achievements) return [];

  for (const achievement of Object.keys(achievements)) {
    const unlockedAchievement = achievements[achievement];

    const unlockTime = Number(
      unlockedAchievement.slice(1, -1).replace("unlocked = true, time = ", "")
    );

    if (!isNaN(unlockTime)) {
      newUnlockedAchievements.push({
        name: achievement.replace(/"/g, ``),
        unlockTime: unlockTime * 1000,
      });
    }
  }

  return newUnlockedAchievements;
};

import axios, { AxiosError, AxiosInstance } from "axios";
import { WindowManager } from "./window-manager";
import url from "url";
import { uploadGamesBatch } from "./library-sync";
import { clearGamesRemoteIds } from "./library-sync/clear-games-remote-id";
import { networkLogger as logger } from "./logger";
import { UserNotLoggedInError /*, SubscriptionRequiredError*/ } from "@shared";
import { appVersion } from "@main/constants";
import { getUserData } from "./user/get-user-data";
import { db } from "@main/level";
import { levelKeys } from "@main/level/sublevels";
import type { Auth, User } from "@types";
import { SSEClient } from "./sse";
import { sanitizeNetworkLogPayload } from "./network-log-payload";

export interface HydraApiOptions {
  needsAuth?: boolean;
  needsSubscription?: boolean;
  ifModifiedSince?: Date;
  ifNoneMatch?: string;
  validateStatus?: (status: number) => boolean;
  signal?: AbortSignal;
}

interface HydraApiUserAuth {
  authToken: string;
  refreshToken: string;
  expirationTimestamp: number;
  subscription: { expiresAt: Date | string | null } | null;
}

export class HydraApi {
  private static instance: AxiosInstance;

  private static readonly EXPIRATION_OFFSET_IN_MS = 1000 * 60 * 5; // 5 minutes
  private static readonly ADD_LOG_INTERCEPTOR = true;

  private static secondsToMilliseconds(seconds: number) {
    return seconds * 1000;
  }

  private static userAuth: HydraApiUserAuth = {
    authToken: "",
    refreshToken: "",
    expirationTimestamp: 0,
    subscription: null,
  };

  public static isLoggedIn() {
    return this.userAuth.authToken !== "";
  }

  public static hasActiveSubscription() {
    const expiresAt = new Date(this.userAuth.subscription?.expiresAt ?? 0);
    return expiresAt > new Date();
  }

  public static updateUserSubscription(
    subscription?: { expiresAt: Date | string | null } | null
  ) {
    this.userAuth.subscription = subscription
      ? { expiresAt: subscription.expiresAt }
      : null;
  }

  static async handleExternalAuth(uri: string) {
    const { payload } = url.parse(uri, true).query;

    const decodedBase64 = atob(payload as string);
    const jsonData = JSON.parse(decodedBase64);

    const { accessToken, expiresIn, refreshToken, workwondersJwt } = jsonData;

    const now = new Date();

    const tokenExpirationTimestamp =
      now.getTime() +
      this.secondsToMilliseconds(expiresIn) -
      this.EXPIRATION_OFFSET_IN_MS;

    this.userAuth = {
      authToken: accessToken,
      refreshToken: refreshToken,
      expirationTimestamp: tokenExpirationTimestamp,
      subscription: null,
    };

    const { AchievementWatcherManager } = await import(
      "./achievements/achievement-watcher-manager"
    );
    AchievementWatcherManager.resetSessionState();

    logger.log(
      "Sign in received. Token expiration timestamp:",
      tokenExpirationTimestamp
    );

    db.put<string, Auth>(
      levelKeys.auth,
      {
        accessToken,
        refreshToken,
        tokenExpirationTimestamp,
        workwondersJwt,
      },
      { valueEncoding: "json" }
    );

    await getUserData().then((userDetails) => {
      if (userDetails?.subscription) {
        this.updateUserSubscription({
          expiresAt: userDetails.subscription.expiresAt
            ? new Date(userDetails.subscription.expiresAt)
            : null,
        });
      }
    });

    if (WindowManager.mainWindow) {
      WindowManager.mainWindow.webContents.send("on-signin");
      await clearGamesRemoteIds();
      void uploadGamesBatch();

      SSEClient.close();
      SSEClient.connect();

      const { syncDownloadSourcesFromApi } = await import("./user");
      syncDownloadSourcesFromApi();
    }
  }

  static async handleSignOut() {
    this.userAuth = {
      authToken: "",
      refreshToken: "",
      expirationTimestamp: 0,
      subscription: null,
    };

    const { AchievementWatcherManager } = await import(
      "./achievements/achievement-watcher-manager"
    );
    AchievementWatcherManager.resetSessionState();

    this.sendSignOutEvent();
    this.post("/auth/logout", {}, { needsAuth: false }).catch(() => {});
  }

  static async setupApi() {
    let baseURL = import.meta.env.MAIN_VITE_API_URL;

    try {
      const { db, levelKeys } = await import("@main/level");
      const prefs = (await db.get(levelKeys.userPreferences, {
        valueEncoding: "json",
      })) as any;

      if (prefs?.serverType === "local") {
        baseURL = "http://localhost:3001";
      } else if (prefs?.serverType === "custom" && prefs?.customBackendUrl) {
        baseURL = prefs.customBackendUrl;
      }
    } catch (err) {
      // Ignore missing preferences
    }

    this.instance = axios.create({
      baseURL,
      headers: { "User-Agent": `Hydra Launcher v${appVersion}` },
    });

    if (this.ADD_LOG_INTERCEPTOR) {
      this.instance.interceptors.request.use(
        (request) => {
          logger.log(" ---- REQUEST -----");
          logger.log(
            request.method,
            request.url,
            sanitizeNetworkLogPayload({
              params: request.params ?? null,
              data: request.data ?? null,
            })
          );
          return request;
        },
        (error) => {
          logger.error("request error", error);
          return Promise.reject(error);
        }
      );
      this.instance.interceptors.response.use(
        (response) => {
          logger.log(" ---- RESPONSE -----");
          logger.log(
            response.status,
            response.config.method,
            response.config.url,
            sanitizeNetworkLogPayload(response.data)
          );
          return response;
        },
        (error) => {
          logger.error(" ---- RESPONSE ERROR -----");
          const config = error.config ?? {};

          logger.error(
            config.method,
            config.baseURL,
            config.url,
            sanitizeNetworkLogPayload({
              headers: config.headers ?? null,
              data: config.data ?? null,
            })
          );
          if (error.response) {
            logger.error(
              "Response error:",
              error.response.status,
              sanitizeNetworkLogPayload(error.response.data)
            );

            return Promise.reject(error as Error);
          }

          if (error.request) {
            const errorData = error.toJSON();
            logger.error("Request error:", errorData.code, errorData.message);
            return Promise.reject(
              new Error(
                `Request failed with ${errorData.code} ${errorData.message}`
              )
            );
          }

          logger.error("Error", error.message);
          return Promise.reject(error as Error);
        }
      );
    }

    const result = await db.getMany<string>([levelKeys.auth, levelKeys.user], {
      valueEncoding: "json",
    });

    const userAuth = result.at(0) as Auth | undefined;
    const user = result.at(1) as User | undefined;

    this.userAuth = {
      authToken: userAuth?.accessToken ?? "",
      refreshToken: userAuth?.refreshToken ?? "",
      expirationTimestamp: userAuth?.tokenExpirationTimestamp ?? 0,
      subscription: user?.subscription
        ? { expiresAt: user.subscription?.expiresAt }
        : null,
    };

    const updatedUserData = await getUserData();

    this.updateUserSubscription(updatedUserData?.subscription);
  }

  private static sendSignOutEvent() {
    WindowManager.sendToAppWindows("on-signout");
  }

  public static async refreshToken() {
    const response = await this.instance.post(`/auth/refresh`, {
      refreshToken: this.userAuth.refreshToken,
    });

    const { accessToken, expiresIn } = response.data;

    const tokenExpirationTimestamp =
      Date.now() +
      this.secondsToMilliseconds(expiresIn) -
      this.EXPIRATION_OFFSET_IN_MS;

    this.userAuth.authToken = accessToken;
    this.userAuth.expirationTimestamp = tokenExpirationTimestamp;

    logger.log(
      "Token refreshed. New expiration:",
      this.userAuth.expirationTimestamp
    );

    await db
      .get<string, Auth>(levelKeys.auth, { valueEncoding: "json" })
      .then((auth) => {
        return db.put<string, Auth>(
          levelKeys.auth,
          {
            ...auth,
            accessToken,
            tokenExpirationTimestamp,
          },
          { valueEncoding: "json" }
        );
      });

    return { accessToken, expiresIn };
  }

  private static async revalidateAccessTokenIfExpired() {
    if (this.userAuth.expirationTimestamp < Date.now()) {
      try {
        await this.refreshToken();
      } catch (err) {
        await this.handleUnauthorizedError(err);
      }
    }
  }

  private static getAxiosConfig() {
    return {
      headers: {
        Authorization: `Bearer ${this.userAuth.authToken}`,
      },
    };
  }

  private static readonly handleUnauthorizedError = async (err) => {
    if (err instanceof AxiosError && err.response?.status === 401) {
      logger.error(
        "401 - Current credentials:",
        sanitizeNetworkLogPayload({
          credentials: this.userAuth,
          response: err.response?.data,
        })
      );

      this.userAuth = {
        authToken: "",
        expirationTimestamp: 0,
        refreshToken: "",
        subscription: null,
      };

      const { AchievementWatcherManager } = await import(
        "./achievements/achievement-watcher-manager"
      );
      AchievementWatcherManager.resetSessionState();

      db.batch([
        {
          type: "del",
          key: levelKeys.auth,
        },
        {
          type: "del",
          key: levelKeys.user,
        },
      ]);

      SSEClient.close();
      this.sendSignOutEvent();
    }

    throw err;
  };

  private static async validateOptions(options?: HydraApiOptions) {
    const needsAuth = options?.needsAuth == undefined || options.needsAuth;
    // const needsSubscription = options?.needsSubscription === true;

    if (needsAuth) {
      if (!this.isLoggedIn()) throw new UserNotLoggedInError();
      await this.revalidateAccessTokenIfExpired();
    }

    // Self-hosted: all cloud features are free, skip subscription check
    // if (needsSubscription && !this.hasActiveSubscription()) {
    //   await this.refreshUserSubscription();
    //
    //   if (!this.hasActiveSubscription()) {
    //     throw new SubscriptionRequiredError();
    //   }
    // }
  }

